/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A9 checkpoint 1/4: first 20 assigned headwords, individually authored. */
'use strict';
const D = globalThis.RA.D;
const q = (w,n,s,p,a,b,c,x,type='meaning') => ({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:type,type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const m = (wrong,right,reason,type='meaning') => ({errorType:type,wrong,right,reason});
const c = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const e = (origin,source) => ({origin,prefix:null,root:null,suffix:null,source});
const src = w => `Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`;
D('bedpan',{etymology:e('透明英语复合词 bed + pan，字面指床边/床上的浅盘，现代专指供卧床者排泄用的便盆；不据此虚构更早词根。',src('bedpan')),contexts:[c('bedpan.s1','医院护理','After surgery, Mr. Lee could not walk to the bathroom, so the nurse placed a bedpan within reach and returned to help him.','李先生手术后无法走到卫生间，护士把便盆放在他够得到的地方，随后回来帮他。','After surgery / Mr. Lee could not walk to the bathroom / so the nurse placed a bedpan within reach / and returned to help him.','bedpan 是 placed 的宾语；within reach 表示放在够得到的范围内。','这里是供卧床者排泄使用的器具义，与普通餐盘无关。')],mistakes:[m('The nurse put the bedpan on the bedside table so the patient could eat soup from it.','The nurse put the tray on the bedside table so the patient could eat soup from it.','bedpan 是便盆，不是盛食物的餐盘；将器具改为 tray 即可。')],quiz:[q('bedpan',1,1,'A bedpan is brought to a patient who?','cannot get out of bed to use a toilet','needs a bowl for breakfast','is going outside for a walk','便盆供卧床者排泄使用。'),q('bedpan',2,1,'Where would a nurse place a bedpan for immediate use?','within the patient’s reach','inside the kitchen oven','on a street corner','护理人员会把便盆放在患者身边。'),q('bedpan',3,1,'The patient is too weak to reach the bathroom, so the nurse fetches a ___.','bedpan','flowerpot','teapot','无法去卫生间时护士会取来便盆。'),q('bedpan',4,1,'Which statement about a bedpan is accurate?','It is a receptacle used by someone confined to bed.','It is a soft cushion placed under a pillow.','It measures body temperature.','bedpan 是供卧床者使用的排泄容器。')]});
D('bedrock',{etymology:e('英语复合词 bed + rock，原指土层下的坚硬岩层；根本基础是由岩层比喻引申出的义项。',src('bedrock')),contexts:[c('bedrock.s2','法律原则','The court treated equal access to counsel as the bedrock of a fair hearing, so it postponed the case until the defendant had a lawyer.','法院把平等获得律师帮助视为公正听证的根本，因此将案件延期到被告有律师为止。','The court treated equal access to counsel as the bedrock of a fair hearing / so it postponed the case / until the defendant had a lawyer.','the bedrock of + 名词表示赖以成立的根本；until 引导时间状语从句。','此处 bedrock 指法律程序赖以成立的基本原则，对应抽象义 s2。')],mistakes:[m('Trust is the bedrock of a reliable partnership, so each side should hide important terms from the other.','Trust is the bedrock of a reliable partnership, so each side should disclose important terms to the other.','信任是合作的根本，隐瞒条款与前半句冲突；将 hide 改为 disclose。')],quiz:[q('bedrock',1,1,'In “the bedrock of a fair system,” bedrock means?','the fundamental basis','a decorative surface','a temporary obstacle','比喻义 bedrock 指体系赖以成立的根本基础。'),q('bedrock',2,1,'A geologist drilling below soil may reach?','bedrock','a courtroom principle','a layer of loose leaves','地质义 bedrock 是土壤下的坚硬岩层。'),q('bedrock',3,2,'Which is the bedrock of a policy?','the basic principle on which it depends','a minor detail added at the end','a short-lived public reaction','抽象义强调制度赖以成立的基础。'),q('bedrock',4,2,'Complete: “Honesty is the ___ of their agreement.”','bedrock','bedpan','bedtime','bedrock 常用于 the bedrock of，表示根本。')]});
D('bedsit',{etymology:e('英式英语中 bed + sitting room 的缩合构词，指兼作卧室和起居室的出租单间；此词的地域用法为英式。',src('bedsit')),contexts:[c('bedsit.s1','租房','The student chose a small bedsit near the hospital because the rent included heating, although she shared the bathroom with two other tenants.','学生选了医院附近的小单间，因为房租含暖气费，不过她得与另外两位租客共用卫生间。','The student chose a small bedsit near the hospital / because the rent included heating / although she shared the bathroom with two other tenants.','bedsit 是可数名词，前有 a；although 引导让步从句。','一间房兼作卧室与起居室、设施共用，符合词条义。')],mistakes:[m('He rented a bedsit with a separate bedroom, living room, and kitchen in three rooms.','He rented a flat with a separate bedroom, living room, and kitchen in three rooms.','bedsit 是一间房兼作卧室与起居室；多房间住宅应称 flat。')],quiz:[q('bedsit',1,1,'What is the usual layout of a bedsit?','one room used as both bedroom and sitting room','a house with several private bedrooms','a hotel room reserved for meetings','bedsit 指卧室与起居室合一的单间。'),q('bedsit',2,1,'A tenant in a bedsit may have to share?','washing facilities','the bed with every neighbor','rent with the landlord’s family','bedsit 常有共用洗漱设施。'),q('bedsit',3,1,'Which advert describes a bedsit?','One furnished room; bathroom shared with tenants.','Three bedrooms, two lounges, and a private garden.','A desk rented by the hour in a library.','单间出租且卫生间共用，符合 bedsit。'),q('bedsit',4,1,'Bedsit is especially associated with?','British English','only Australian legal English','American English as a standard term','bedsit 是常见英式住房词。')]});
D('beet',{etymology:e('英语 beet 源自古英语 bete，借自拉丁语 beta（甜菜）；可指制糖作物，也可指其供食用的根。',src('beet')),contexts:[c('beet.s2','烹饪','For the winter salad, Nia roasted whole beets until tender, then peeled and sliced the dark red roots over the greens.','做冬季沙拉时，妮娅把整颗甜菜根烤软，剥皮后切片铺在蔬菜上。','For the winter salad / Nia roasted whole beets until tender / then peeled and sliced the dark red roots over the greens.','beet 在此为可数名词复数，指食用根；until tender 表示烤至软熟。','句中 beet 是食用甜菜根义 s2，而非制糖作物整体。')],mistakes:[m('The recipe says to grate two beets, but I bought two beet seeds instead.','The recipe says to grate two beets, but I bought two beet roots instead.','食谱要磨碎的是蔬菜根，不是种子；只将 seeds 改为 roots。')],quiz:[q('beet',1,2,'A factory that extracts sugar from beet mainly uses?','the crop grown for its sweet root','the leaves as writing paper','the red color as a metal','作物义的 beet 是种植来制糖的甜菜。'),q('beet',2,2,'In a salad recipe, “slice the beet” means slice?','the edible root','the seed packet','the field','蔬菜语境中的 beet 指甜菜根。'),q('beet',3,1,'Which sentence uses beet for the crop?','Farmers grow beet for the sugar industry.','She added sliced beet to soup.','The roasted beet stained the plate.','grow beet for sugar 指种植甜菜作物。'),q('beet',4,2,'A cook peels a beet before roasting it. What is peeled?','the round edible root','a bag of sugar','a cooking pan','烹饪中剥皮的 beet 是食用根。')]});
D('befit',{etymology:e('古英语 befitten 一类的英语构词，现代通常分析为 be- + fit，核心为“适合、相称”；不延伸到未经核实的更古词根。',src('befit')),contexts:[c('befit.s1','正式礼仪','Given the solemn occasion, a brief moment of silence befitted the ceremony better than a loud celebration.','考虑到场合庄重，片刻肃静比喧闹庆祝更适合这场仪式。','Given the solemn occasion / a brief moment of silence befitted the ceremony / better than a loud celebration.','befit 是及物动词；过去式 befitted 双写 t。','肃静与庄重仪式相称，体现 befit 的得体义。')],mistakes:[m('A noisy joke befitted the minute of silence at the memorial.','A noisy joke suited the casual party after the memorial.','喧闹笑话与默哀不相称；改成与轻松聚会相符的表述。')],quiz:[q('befit',1,1,'An action that befits a formal occasion is?','appropriate to it','deliberately unrelated to it','too expensive to arrange','befit 表示与身份或场合相称。'),q('befit',2,1,'Which subject befits a medal ceremony?','a respectful speech','a prank interrupting the awards','an unrelated shopping list','得体的演讲适合颁奖仪式。'),q('befit',3,1,'Complete: “Such patience ___ a skilled teacher.”','befits','befits to','befit with','befit 后直接接与之相称的人或场合。'),q('befit',4,1,'“The quiet room befitted the reflection.” Befitted is?','the past tense of befit','the plural noun for a room','an adjective meaning noisy','befitted 是 befit 的过去式。')]});
D('befriend',{etymology:e('英语派生动词 befriend 由 be- + friend 构成，表示以朋友身份对待并帮助某人；不把 friend 的更早词源混作该动词专属后缀。',src('befriend')),contexts:[c('befriend.s1','校园互助','When the exchange student arrived without knowing anyone, two classmates befriended her, showed her around campus, and invited her to lunch.','交换生初来乍到谁也不认识，两位同学主动和她交朋友，带她参观校园并邀请她共进午餐。','When the exchange student arrived without knowing anyone / two classmates befriended her / showed her around campus / and invited her to lunch.','befriend 是及物动词，直接接受帮助的人作宾语。','同学为新来的交换生提供陪伴和帮助，符合“友好相待”义。')],mistakes:[m('The guide befriended the lost visitor by refusing to speak to her or give directions.','The guide ignored the lost visitor by refusing to speak to her or give directions.','拒绝交谈指路并非友好帮助；将 befriended 改为 ignored 与后文一致。')],quiz:[q('befriend',1,1,'To befriend a newcomer usually means to?','treat the person kindly and offer companionship','avoid speaking to the person','charge an entrance fee','befriend 指像朋友一样对待并帮助某人。'),q('befriend',2,1,'Which action illustrates befriending a lonely neighbor?','checking in and inviting them for tea','mocking them when they ask for help','pretending not to recognize them','主动关心并邀喝茶体现友好相待。'),q('befriend',3,1,'Choose the grammatical sentence.','The volunteers befriended the new residents.','The volunteers befriended to the residents.','The volunteers befriended with the residents.','befriend 是及物动词，宾语前不加 to 或 with。'),q('befriend',4,1,'A mentor befriends a new employee by?','welcoming and supporting the employee','formally dismissing the employee','keeping the employee isolated','befriend 可指给予新来者友善支持。')]});
D('befuddle',{etymology:e('befuddle 由英语 be- + fuddle 构成；fuddle 与昏沉、混乱相关，具体更早来源不确定，此处只陈述构词及现代义。',src('befuddle')),contexts:[c('befuddle.s1','说明书','The manual listed three nearly identical reset procedures, which befuddled the volunteers until an engineer marked the correct sequence.','手册列出三种几乎相同的重置流程，志愿者因此被弄糊涂，直到工程师标出正确顺序。','The manual listed three nearly identical reset procedures / which befuddled the volunteers / until an engineer marked the correct sequence.','which 引导定语从句；befuddle 的宾语是被弄糊涂的人。','相似流程造成理解混乱，符合 s1，不是酒药造成昏沉的 s2。')],mistakes:[m('The labels befuddled the reader, so she immediately understood every instruction without help.','The labels befuddled the reader, so she could not understand the instructions without help.','befuddle 表示使人难以清楚思考，不能同时导致立即全部理解。')],quiz:[q('befuddle',1,1,'Confusing instructions may befuddle a reader by?','making it hard to think clearly','making every step obvious at once','moving the reader to another room','befuddle 的常见义是使人迷惑、思路不清。'),q('befuddle',2,2,'If strong drink befuddles someone, the person may become?','dull and mentally unclear','more alert than usual','unable to hear sounds','酒使人 befuddled 可指昏沉迟钝。'),q('befuddle',3,1,'The two similar maps ___ the class.','befuddled','befuddlingly','befuddle to','过去式 befuddled 直接接被弄糊涂的人。'),q('befuddle',4,1,'A befuddled witness is likely?','confused and unable to organize an account','certain of every detail','angry only because the room is cold','befuddled 描写思路混乱、糊涂。')]});
D('beget',{etymology:e('古英语 begietan“得到、取得”的后代形式；英语中保留“生育”这一旧式用法，并引申为“引起、导致”。',src('beget')),contexts:[c('beget.s2','社会后果','When officials punished every peaceful complaint, their harsh response begot more distrust, and fewer residents were willing to report problems.','官员惩罚每一次和平投诉，严厉做法因而引发更多不信任，愿意报告问题的居民也更少。','When officials punished every peaceful complaint / their harsh response begot more distrust / and fewer residents were willing to report problems.','beget 的过去式是 begot（也见 begotten）；主语是导致结果的行为。','严厉回应造成不信任，使用“引起、产生”义 s2。')],mistakes:[m('The report says fear begets trust, so frightened residents become more willing to speak openly.','The report says fear begets distrust, so frightened residents become less willing to speak openly.','恐惧引发不信任；trust 与后文“不敢公开说”矛盾。')],quiz:[q('beget',1,2,'In “violence begets violence,” begets means?','causes more violence to arise','prevents violence from happening','records violence in a book','beget 的比喻义是引起、导致。'),q('beget',2,1,'In an old family record, “he begot a son” means?','he became the father of a son','he adopted a new surname','he purchased a house','旧式 beget 指生育、成为父亲。'),q('beget',3,2,'Choose the past form: “The policy ___ new problems.”','begot','begetted','begoten','beget 的常见过去式是 begot。'),q('beget',4,2,'Which illustrates the causal sense of beget?','a careless rumor produces further suspicion','a calendar lists dates without affecting anyone','a locked box prevents any event','beget 表示某事产生或引发另一结果。')]});
D('beggar',{etymology:e('beggar 由英语 beg 加施事名词后缀 -ar/-er 构成，指乞讨者；动词“使变穷、使不堪设想”是后续发展义。',src('beggar')),contexts:[c('beggar.s2','城市预算','Replacing the flooded bridge twice in one year would beggar the small town, so engineers proposed a cheaper design with higher supports.','一年内两次重建洪水冲毁的桥会使小镇财政不堪重负，因此工程师提出成本较低、桥墩更高的设计。','Replacing the flooded bridge twice in one year / would beggar the small town / so engineers proposed a cheaper design / with higher supports.','beggar 作及物动词，表示使某人陷入贫困；would 表示假设后果。','重建费用可能压垮小镇财力，对应动词义 s2。')],mistakes:[m('The donation beggared the family by giving them enough money to pay every debt.','The donation helped the family by giving them enough money to pay every debt.','捐款助其还债是帮助而非使其贫困；只将 beggared 改为 helped。')],quiz:[q('beggar',1,1,'A beggar is someone who?','asks the public for money or food','inspects bridges for safety','collects city taxes','名词义 beggar 指靠乞讨的人。'),q('beggar',2,2,'“The repair bill would beggar the village” means it would?','leave the village extremely poor','make the village wealthy','repair roads for free','动词义 beggar 是使某人陷入贫困。'),q('beggar',3,1,'Which noun describes someone asking for alms?','a beggar','a bidder','a benefactor','beggar 的名词义是乞丐。'),q('beggar',4,2,'Another failed harvest could ___ the farm.','beggar','beggar to','be beggar of','作动词时 beggar 可直接接受影响的机构。')]});
D('begrime',{etymology:e('英语派生词 be- + grime；grime 指黏附的厚尘垢或烟垢，begrime 表示使某物蒙上污垢。',src('begrime')),contexts:[c('begrime.s1','旧厂房','Years of coal smoke had begrimed the factory windows, leaving only a narrow strip of clear glass where the caretaker wiped them each morning.','多年的煤烟把工厂窗户熏得满是污垢，管理员每天擦过的地方只留下窄窄一条透明玻璃。','Years of coal smoke had begrimed the factory windows / leaving only a narrow strip of clear glass / where the caretaker wiped them each morning.','过去完成时 had begrimed 表示清洁之前烟垢已积累；现在分词短语说明结果。','煤烟使窗户沾上厚垢，符合弄脏义。')],mistakes:[m('The rain begrimed the windows and removed every trace of dust from the glass.','The rain cleaned the windows and removed every trace of dust from the glass.','去掉所有灰尘是清洁而非弄脏；将 begrimed 换成 cleaned。')],quiz:[q('begrime',1,1,'To begrime a window is to?','cover it with dirt or soot','polish it until spotless','replace its frame','begrime 指使表面沾上厚尘垢。'),q('begrime',2,1,'What could begrime a white wall?','smoke from a coal stove','a clean coat of paint','a dry cloth removing dust','煤烟能使墙面沾黑垢。'),q('begrime',3,1,'Oil and ash ___ the worker’s sleeves.','begrimed','brightened','befitted','begrime 表示使衣物沾污。'),q('begrime',4,1,'A begrimed chimney is?','covered with soot and grime','freshly painted and clean','made entirely of glass','begrimed 描写覆盖污垢的状态。')]});
D('beguile',{etymology:e('中古英语 begilen 源于 be- + guile（欺骗、诡计），现代义发展出以魅力引诱、欺骗，以及使着迷、愉快消磨时间。',src('beguile')),contexts:[c('beguile.s3','旅途','To beguile the long train ride, Sam listened to his grandmother’s stories and watched rain move across the fields.','为了愉快地打发漫长的火车旅程，萨姆听奶奶讲故事，看雨水掠过田野。','To beguile the long train ride / Sam listened to his grandmother’s stories / and watched rain move across the fields.','不定式 To beguile 表示目的，宾语是时间段 the long train ride。','听故事看风景让旅程过得愉快，对应“消磨时光”义 s3。')],mistakes:[m('They beguiled the afternoon by sitting silently, bored and wishing it would end.','They endured the afternoon by sitting silently, bored and wishing it would end.','无聊地盼望时间快结束是忍受而非愉快消遣；将 beguiled 改为 endured。')],quiz:[q('beguile',1,1,'A smooth talker may beguile a customer by?','charming the customer into a mistaken choice','showing facts plainly with no persuasion','repairing a broken chair','beguile 可指用魅力或花言巧语诱骗。'),q('beguile',2,2,'A story that beguiles its audience?','holds their interest and charms them','makes them leave from boredom','gives an exact timetable','beguile 也指迷住、吸引。'),q('beguile',3,3,'“They beguiled the wait with a word game” means they?','spent the waiting time pleasantly','tricked the clock into stopping','cancelled the appointment','beguile time 指愉快地打发时间。'),q('beguile',4,3,'Which activity could beguile a rainy afternoon?','reading an absorbing novel for pleasure','staring at the clock in frustration','turning off every light and leaving','有趣的阅读能愉快地消磨时间。')]});
D('behavioral',{etymology:e('美式英语 behavior + 形容词后缀 -al；behavior 是由 behave 派生的名词。behavioral 与英式 behaviourial? 无；标准英式对应词为 behavioural。',src('behavioral')),contexts:[c('behavioral.s1','心理学研究','The clinic used a behavioral chart to record how often the child left his seat, then discussed the pattern with his parents.','诊所用行为记录表记下孩子离开座位的次数，然后与家长讨论这一模式。','The clinic used a behavioral chart / to record how often the child left his seat / then discussed the pattern with his parents.','behavioral 修饰 chart；how often 引导 record 的间接疑问内容。','记录可观察行为而非身体结构，符合行为相关义。')],mistakes:[m('The researchers called it a behavioral study because it measured participants’ bone length only.','The researchers called it an anatomical study because it measured participants’ bone length only.','只测骨骼长度研究的是身体结构，不是行为；换成 anatomical。')],quiz:[q('behavioral',1,1,'A behavioral study focuses on?','what people or animals do','the chemical formula of a rock','the shape of a building','behavioral 与可观察行为有关。'),q('behavioral',2,1,'Which is a behavioral measure in a classroom?','how often pupils raise their hands','the color of classroom walls','the length of each desk','举手次数记录的是行为。'),q('behavioral',3,1,'The team tracked ___ changes after a new routine.','behavioral','behave','behaviorism','behavioral 作形容词修饰 changes。'),q('behavioral',4,1,'A behavioral chart would record?','the frequency of a student’s actions','the student’s blood type only','the building’s construction date','行为记录表追踪动作或反应。')]});
D('behaviorism',{etymology:e('behavior + -ism 构成的学说名称，20世纪初用于心理学；行为主义以可观察行为解释学习和反应，不等同于所有现代心理学。',src('behaviorism')),contexts:[c('behaviorism.s1','心理学史','The lecturer explained that behaviorism shaped early training research because researchers emphasized observable responses rather than relying only on reports of private thoughts.','讲师解释说，行为主义影响了早期训练研究，因为研究者强调可观察的反应，而不只依赖对私人想法的报告。','The lecturer explained / that behaviorism shaped early training research / because researchers emphasized observable responses / rather than relying only on reports of private thoughts.','behaviorism 作主语；rather than 对照 emphasized 与 relying。','强调可观察刺激—反应而非内在思维报告，对应理论义。')],mistakes:[m('Behaviorism explains learning only by measuring private thoughts that nobody can observe.','Behaviorism explains learning by emphasizing observable behavior and responses.','原句把不可观察想法说成该理论唯一依据，与其核心方法相反。')],quiz:[q('behaviorism',1,1,'Behaviorism traditionally explains learning by focusing on?','observable behavior and responses','dream meanings alone','the chemical makeup of bones','行为主义重视可观察刺激和反应。'),q('behaviorism',2,1,'A behaviorist experiment is most likely to record?','a measurable response to a cue','a guess about an invisible feeling only','the laboratory floor color','可测量的反应是行为主义关注对象。'),q('behaviorism',3,1,'The suffix -ism helps mark behaviorism as?','a theory or system of ideas','the past tense of a verb','a plural noun for people','-ism 常构成学说或思想体系名称。'),q('behaviorism',4,1,'Which classroom practice reflects behaviorist learning theory?','tracking how a reward changes repeated responses','asking about unrelated dreams','measuring window size','记录奖励如何改变行为反应，契合行为主义。')]});
D('behaviorist',{etymology:e('behaviorist 由 behavior + -ist 构成，指支持或实践 behaviorism 的人；美式常写 behavior，英式常见 behaviourist。',src('behaviorist')),contexts:[c('behaviorist.s1','实验心理学','The behaviorist repeated the same signal-and-reward trial with each animal and recorded the response before drawing a conclusion.','这位行为主义者对每只动物重复相同的信号与奖励实验，并先记录反应再得出结论。','The behaviorist repeated the same signal-and-reward trial / with each animal / and recorded the response / before drawing a conclusion.','behaviorist 是单数可数名词；before drawing 表示先记录、后下结论。','人物以观察动物反应研究行为主义，符合 s1。')],mistakes:[m('The behaviorist refused to study observable actions and focused only on unseen thoughts.','The behaviorist studied observable actions and recorded the responses.','行为主义研究侧重可观察行为；改写后符合其方法。')],quiz:[q('behaviorist',1,1,'A behaviorist is someone who?','supports or applies behaviorism','designs bicycles for a living','writes only biographies','behaviorist 指行为主义者。'),q('behaviorist',2,1,'What might a behaviorist record in a trial?','a subject’s response after a signal','the researcher’s shoe color','an unrelated train schedule','可能记录刺激后的可观察反应。'),q('behaviorist',3,1,'Choose the person noun: “The ___ studied learned responses.”','behaviorist','behavioral','behaviorism','-ist 构成人或实践者名称。'),q('behaviorist',4,1,'The common British spelling is?','behaviourist','behavorist','behaviorest','英式拼写通常为 behaviourist。')]});
D('behavioural',{etymology:e('英式拼写 behaviour + -al；美式对应词为 behavioral。拼写差异不改变“与行为有关”的词义。',src('behavioural')),contexts:[c('behavioural.s1','教育支持','The school introduced a behavioural plan that rewarded the pupil for waiting his turn and speaking calmly during group work.','学校制定行为计划，奖励学生在小组活动中等待轮次并平静发言。','The school introduced a behavioural plan / that rewarded the pupil / for waiting his turn and speaking calmly during group work.','behavioural 修饰 plan；that 从句说明计划如何奖励学生。','计划针对可观察的举止，符合行为义，且采用英式拼写。')],mistakes:[m('The British report uses behavioural throughout, but its editor changed each instance to behaviorall.','The British report uses behavioural throughout, and its editor retained that spelling.','behaviorall 多了一个 l；英式标准拼写是 behavioural。','spelling')],quiz:[q('behavioural',1,1,'A behavioural plan is mainly concerned with?','actions and conduct','the biography of a school founder','the formula of a rock','behavioural 表示与行为有关。'),q('behavioural',2,1,'Which is the standard British spelling?','behavioural','behavioral','behavourial','英式 behaviour 保留 u。'),q('behavioural',3,1,'Choose the natural phrase.','behavioural pattern','behaviour patternal','behaviourally plan','behavioural 作形容词修饰 pattern。'),q('behavioural',4,1,'A behavioural observation would record?','what a person actually does','only the person’s birthplace','furniture prices','行为观察记录实际举止。')]});
D('belie',{etymology:e('古英语 beleogan“用谎言欺骗、背弃”是该词早期来源；现代 belie 常指事实显示某印象并不真实，或表象掩盖真实情感。',src('belie')),contexts:[c('belie.s1','人物描写','Although Mara spoke softly, her precise questions belied the assumption that she had not prepared for the hearing.','玛拉虽轻声说话，但精准的问题足以证明“她没有准备听证会”的假设并不成立。','Although Mara spoke softly / her precise questions belied the assumption / that she had not prepared for the hearing.','belie 的主语是事实或迹象，宾语是被证明为假的印象。','精准提问与“未准备”不符，体现 s1。')],mistakes:[m('Her bright smile belied her happiness, showing she was genuinely delighted.','Her bright smile reflected her happiness, showing she was genuinely delighted.','若笑容显示她确实开心，就不是与开心相矛盾；将 belied 换成 reflected。')],quiz:[q('belie',1,1,'If evidence belies a rumor, it?','shows the rumor is false','repeats the rumor word for word','proves the rumor was printed','belie 可表示证明说法不真实。'),q('belie',2,2,'A calm voice may belie anger if it?','hides the anger behind a calm appearance','makes the anger obvious','removes the speaker’s voice','belie 也可指外表掩饰真实情绪。'),q('belie',3,1,'Which sentence uses belie naturally?','Empty shelves belied the shop’s claim that stock was plentiful.','Empty shelves belied the fact they were empty.','The shelves belied on the floor.','空货架揭穿库存充足的说法，宾语是被证明不实的判断。'),q('belie',4,1,'Belie most often links?','evidence or appearance with a false impression','a person with a home address','a price with a receipt','belie 表示迹象与印象不符或揭示其虚假。')]});
D('belle',{etymology:e('英语 belle 借自法语 belle“美丽的女子”，为 beau 的阴性形式；常见于 belle of the ball 等表达。',src('belle')),contexts:[c('belle.s1','舞会','At the village dance, the newly crowned belle of the ball thanked the band and returned to the floor with her friends.','在村舞会上，新评出的舞会佳人向乐队致谢，然后和朋友回到舞池。','At the village dance / the newly crowned belle of the ball thanked the band / and returned to the floor with her friends.','belle of the ball 是固定表达；crowned 在此作形容词，表示获选。','belle 指舞会中公认的美丽女子，符合词条义。')],mistakes:[m('The newspaper called the rusty tractor the belle of the ball because it was the most beautiful young woman there.','The newspaper called the young woman the belle of the ball because she was the most beautiful person there.','belle 指女子，不能指拖拉机；改正描述对象。')],quiz:[q('belle',1,1,'The belle of the ball is traditionally?','the most admired beautiful woman at the dance','the ticket seller at the entrance','the musician who arrives last','该短语指舞会中最引人注目的美女。'),q('belle',2,1,'Which phrase uses belle traditionally?','the belle of the town','a belle of machine oil','two belles of the ball were men','belle 的英语传统义为美女。'),q('belle',3,1,'Belle entered English from?','French','Japanese','Old Norse','belle 是法语借词。'),q('belle',4,1,'Choose the standard phrase.','the belle of the ball','the bell of the belle','the belle to the ball','常见搭配为 belle of the ball。')]});
D('belligerent',{etymology:e('借自拉丁语 belligerantem，源于 belligerare“作战”，由 bellum“战争”与 gerere“进行”组成；现代形容人时常指好斗挑衅。',src('belligerent')),contexts:[c('belligerent.s1','会议冲突','When the chair asked him to wait for his turn, the belligerent speaker shouted over the other delegates and threatened to leave.','主席请他等候发言时，这名好斗的发言者却盖过他人声音大喊并威胁离开。','When the chair asked him to wait for his turn / the belligerent speaker shouted over the other delegates / and threatened to leave.','belligerent 修饰 speaker；shout over 表示大声盖过他人发言。','对方仅要求轮候，他却挑衅吼叫，符合好斗义 s1。')],mistakes:[m('The belligerent delegate apologized calmly, accepted the ruling, and invited others to speak first.','The cooperative delegate apologized calmly, accepted the ruling, and invited others to speak first.','平静道歉并让他人先说表现合作而非好斗；改为 cooperative。')],quiz:[q('belligerent',1,1,'A belligerent person is likely to?','act aggressively and be ready to fight','avoid disagreement politely','fall asleep during a discussion','belligerent 形容好斗、容易挑衅的人。'),q('belligerent',2,2,'Belligerent nations are nations?','engaged in a war or formal conflict','neutral and uninvolved in conflict','newly formed and unrecognized','国际关系义指交战中的国家。'),q('belligerent',3,1,'Which behavior is most belligerent?','threatening a colleague during a minor disagreement','quietly asking for clarification','accepting a compromise','威胁同事体现挑衅好斗态度。'),q('belligerent',4,1,'Choose the best noun phrase.','a belligerent reply','a belligerent peaceful surrender','belligerent to answer','belligerent 可修饰 reply，表示答复带挑衅。')]});
D('bellows',{etymology:e('古英语 belig“袋、皮囊”的复数形式发展为 bellows；风箱通过挤压鼓风，现代词形通常以复数使用。',src('bellows')),contexts:[c('bellows.s1','铁匠铺','The apprentice worked the bellows steadily so a strong stream of air kept the charcoal fire hot enough for the iron to glow.','学徒有节奏地压动风箱，让强劲气流维持炭火温度，直到铁料烧红。','The apprentice worked the bellows steadily / so a strong stream of air kept the charcoal fire hot enough / for the iron to glow.','work the bellows 表示操作风箱；so 引导结果或目的从句。','器具被挤压向炉火鼓风，符合风箱义。')],mistakes:[m('The blacksmith pumped the bellows to remove air from the forge and extinguish the fire.','The blacksmith pumped the bellows to force air into the forge and intensify the fire.','风箱把空气鼓入炉中助燃，并非抽走空气；修正气流方向和结果。')],quiz:[q('bellows',1,1,'A blacksmith uses bellows to?','force air toward a fire','measure iron’s weight','cut metal sheets','风箱把空气鼓向炉火。'),q('bellows',2,1,'Bellows work mainly by?','being squeezed to push out air','being filled with water and boiled','being spun like a wheel','挤压风箱使空气从出口喷出。'),q('bellows',3,1,'“The bellows are beside the forge.” Bellows is normally treated as?','a plural-form noun','a singular adjective','a past-tense verb','bellows 通常用复数形式，搭配 are。','grammar'),q('bellows',4,1,'Which object is most likely to have bellows?','a hand-operated tool for blowing air','a ruler for drawing a line','a jar for preserving fruit','风箱是一种鼓风工具。')]});
D('belter',{etymology:e('非正式英语 belter 由动词 belt（以强劲声音唱出，亦可指猛击）加 -er 构成；“特别出色的东西”是口语引申，地域色彩依语境而定。',src('belter')),contexts:[c('belter.s2','现场演出','The singer saved the loudest, most emotional number for the finale, and the audience called it a belter as they rose to applaud.','歌手把最响亮、最动情的一首歌留到压轴，观众起立鼓掌，称它是一首劲歌。','The singer saved the loudest, most emotional number for the finale / and the audience called it a belter / as they rose to applaud.','call + 宾语 + 名词补足语；a belter 此处指高亢有力的歌曲。','语境将 belter 用于演唱有力的歌，对应 s2。')],mistakes:[m('The audience called the barely audible lullaby a belter because nobody could hear it.','The audience called the loud, powerful song a belter because everyone could hear it.','歌曲义 belter 强调响亮有力；“几乎听不见”与之矛盾。')],quiz:[q('belter',1,1,'Informally, “That match was a belter” means it was?','an impressively good match','cancelled before play','played with no teams','belter 可口语称特别出色的事物。'),q('belter',2,2,'A belter of a song is typically?','performed loudly and with strong feeling','whispered so nobody hears','written only for silent film','歌曲义指高亢有力的演唱。'),q('belter',3,1,'Which sentence praises an event?','The final was a belter from start to finish.','The final was a belter because it never happened.','The final belterly the players.','口语名词 belter 可以称赞精彩赛事。'),q('belter',4,2,'If a singer belts out a song, a belter may be?','a powerful, high-energy song','a song with no sound','a song sung only by a machine','belter 与有力、高亢地唱相关。')]});
/* A9 checkpoint 2/4: entries 21–40. */
D('beluga',{etymology:e('英语 beluga 借自俄语 белуга（beluga），与 белый（belyi，“白色的”）相关，得名于白鲸的浅色；该词也用于欧鳇鱼子酱。',src('beluga')),contexts:[c('beluga.s1','北极生态','A beluga surfaced beside the research boat, exhaled through its blowhole, and stayed near the ice floe while the team counted the pod.','一头白鲸在科考船旁浮出水面，从呼吸孔呼气，并留在浮冰附近，供研究队清点鲸群。','A beluga surfaced beside the research boat / exhaled through its blowhole / and stayed near the ice floe / while the team counted the pod.','beluga 作可数名词，复数可用 belugas；surface 表示浮出水面。','动物在北极海域浮现，使用白鲸义 s1，而非鲟鱼或鱼子酱义。')],mistakes:[m('The beluga surfaced in the Arctic and was identified as a huge sturgeon whose eggs make caviar.','The beluga surfaced in the Arctic and was identified as a small white whale.','北极海域浮现的白色鲸是 beluga 的鲸义；产鱼子酱的是另一种欧鳇。')],quiz:[q('beluga',1,1,'A beluga that surfaces beside an Arctic boat is a?','small white whale','type of freshwater trout','bird that lives on sea ice','beluga 的一个常见义是北极白鲸。'),q('beluga',2,2,'Beluga caviar comes from the eggs of a?','large sturgeon','white whale','polar bear','鱼子酱义的 beluga 指欧鳇这种大型鲟鱼。'),q('beluga',3,1,'Which detail points to the whale sense of beluga?','It breathes at the surface of Arctic water.','Its eggs are cured for caviar.','It grows in a garden pond.','在北极水面呼吸指白鲸义。'),q('beluga',4,2,'A menu advertising beluga caviar is referring to?','sturgeon roe','whale milk','a white sea bird','beluga caviar 是欧鳇鱼卵制品。')]});
D('bemoan',{etymology:e('英语 bemoan 由 be- + moan 构成，核心沿用 moan“哀叹”的动作，作及物动词表示为某损失或境况悲叹、抱怨。',src('bemoan')),contexts:[c('bemoan.s2','城市生活','Commuters bemoaned the new evening fare, arguing that the extra charge made even a short trip home unnecessarily expensive.','通勤者抱怨新的晚间票价，认为额外收费让哪怕一段很短的回家路都变得不必要地昂贵。','Commuters bemoaned the new evening fare / arguing that the extra charge made even a short trip home unnecessarily expensive.','bemoan 是及物动词，直接接所哀叹或抱怨的对象；arguing 补充抱怨理由。','语境是对票价的哀怨抱怨，对应 s2；不是单纯悲悼损失。')],mistakes:[m('The residents bemoaned the excellent new bus service and said they were delighted with it.','The residents praised the excellent new bus service and said they were delighted with it.','对改善感到高兴是赞扬，不是 bemoan；换为 praised 与后文一致。')],quiz:[q('bemoan',1,1,'People who bemoan a loss usually?','express sadness or regret about it','celebrate it as a success','measure its weight','bemoan 指对损失表示悲伤惋惜。'),q('bemoan',2,2,'To bemoan a fare increase is to?','complain sadly about the higher price','collect the new fares','forget where the bus stops','bemoan 也可指带着哀怨抱怨。'),q('bemoan',3,1,'Choose the correct completion: “Farmers bemoaned ___.”','the loss of their crops','the plentiful harvest they welcomed','a map they never saw','bemoan 后接所哀叹的事情。'),q('bemoan',4,2,'Which sentence uses bemoan for a complaint?','She bemoaned the long wait at the clinic.','She bemoaned the happy news by cheering loudly.','She bemoaned to the clinic the waiting.','bemoan 可指哀怨地抱怨某种处境。')]});
D('benediction',{etymology:e('借自拉丁语 benedictio“祝福”，源于 benedicere“说好话、祝福”，由 bene“好”与 dicere“说”组成；英语多用于宗教仪式结束的祝祷。',src('benediction')),contexts:[c('benediction.s1','宗教仪式','At the end of the service, the minister offered a short benediction and the congregation remained silent until the final prayer was complete.','礼拜结束时，牧师作了简短祝祷，会众一直安静到最后一段祷告结束。','At the end of the service / the minister offered a short benediction / and the congregation remained silent / until the final prayer was complete.','offer a benediction 是名词搭配；until 引导时间状语从句。','祝祷出现在宗教仪式末尾，符合该词的典型义项。')],mistakes:[m('The service ended with a benediction cursing the congregation and wishing them harm.','The service ended with a benediction blessing the congregation and wishing them well.','祝祷是祝福而非诅咒；将 cursing 改为 blessing 使定义一致。')],quiz:[q('benediction',1,1,'A minister gives a benediction to?','speak a blessing, often at a service’s end','announce the weather forecast','collect donations at the door','benediction 指说出的祝福，尤指仪式结束祝祷。'),q('benediction',2,1,'Which is most likely a benediction?','a closing prayer asking for peace','a legal notice of eviction','a list of the choir members','结束祷告祝愿平安符合 benediction。'),q('benediction',3,1,'The Latin elements behind benediction point to?','speaking well or blessing','counting stones','carrying a weapon','bene 与 dicere 表示好与说，形成祝福义。'),q('benediction',4,1,'Complete the phrase: “The priest closed the service with a ___.”','benediction','benefaction','bidder','礼拜结束时可作 benediction。')]});
D('benefaction',{etymology:e('英语经法语或拉丁语借入 benefaction，源自拉丁语 benefactio/benefacere“行善、施惠”，由 bene“好”与 facere“做”组成；可指捐助行为或所给的帮助。',src('benefaction')),contexts:[c('benefaction.s1','公共捐助','The archive acknowledged an anonymous benefaction that paid for climate controls, allowing fragile letters to be preserved for another generation.','档案馆感谢一笔匿名捐赠，它支付了温控设备费用，使易损信件得以再保存一代人。','The archive acknowledged an anonymous benefaction / that paid for climate controls / allowing fragile letters to be preserved for another generation.','benefaction 作可数名词，that 从句说明捐助用途；allowing 短语表示结果。','捐款支持机构保存文献，是捐赠/善举义。')],mistakes:[m('The university rejected every benefaction and received no money or help from anyone.','The university rejected every donation and received no money or help from anyone.','benefaction 本身指给予的捐助或善举；若全盘拒收、未获帮助，不能称其收到了 benefaction。')],quiz:[q('benefaction',1,1,'A benefaction to a library is?','money or help given to support it','a fine imposed for late returns','a book borrowed and never returned','benefaction 指给予机构的钱或帮助。'),q('benefaction',2,1,'Which act is a benefaction?','funding repairs to a public reading room','charging visitors for breaking a rule','closing a library without explanation','资助公共阅览室是捐助善举。'),q('benefaction',3,1,'The Latin formation of benefaction combines ideas of?','doing good','speaking angrily','measuring twice','bene + facere 与行善施惠相关。'),q('benefaction',4,1,'“The museum was saved by a private ___.”','benefaction','belligerence','bidding','私人捐助可以挽救博物馆。')]});
D('beneficent',{etymology:e('借自拉丁语 beneficent-，源于 beneficus“行善的”，与 bene“好”及 facere“做”同源；形容人乐于施惠，也可形容产生有益结果的事物。',src('beneficent')),contexts:[c('beneficent.s1','奖学金','A beneficent donor created a scholarship for students whose families could not cover tuition, and asked that the award remain open to applicants from any region.','一位仁厚的捐赠者为无力承担学费的学生设立奖学金，并要求各地申请者都能参加评选。','A beneficent donor created a scholarship / for students whose families could not cover tuition / and asked that the award remain open to applicants from any region.','beneficent 修饰 donor；whose 引导定语从句，说明学生家庭的经济状况。','捐赠者慷慨帮助他人，体现慈善、乐于施惠义。')],mistakes:[m('The beneficent donor deliberately removed the scholarship and left needy students without support.','The cruel donor deliberately removed the scholarship and left needy students without support.','故意撤掉助学金并弃学生于不顾并非行善；改为 cruel 才符合行为。')],quiz:[q('beneficent',1,1,'A beneficent person is?','kind and generous toward others','eager to cause harm','unable to make a decision','beneficent 描写仁厚、乐于施惠。'),q('beneficent',2,1,'A beneficent policy would most likely?','produce a helpful result','make a useful service less available','punish people without reason','beneficent 可形容产生有益结果。'),q('beneficent',3,1,'Choose the natural phrase.','a beneficent ruler who funds clinics','a beneficent injury that harms everyone','beneficent of the staircase','形容统治者慷慨资助诊所，符合词义。'),q('beneficent',4,1,'The word is historically related to Latin elements meaning?','good and doing','war and speaking','two and years','bene + facere 组合与行善有关。')]});
D('beneficiary',{etymology:e('英语 beneficiary 经法语借自晚期拉丁语 beneficiarius，源自 beneficium“恩惠、利益”；可指遗嘱、保单或项目中的受益人。',src('beneficiary')),contexts:[c('beneficiary.s1','保险','After checking the policy, Nora named her sister as the sole beneficiary, so the insurer would pay the benefit directly to her if Nora died.','核对保单后，诺拉把姐姐指定为唯一受益人，这样若她去世，保险公司会直接向姐姐支付保险金。','After checking the policy / Nora named her sister as the sole beneficiary / so the insurer would pay the benefit directly to her / if Nora died.','name A as beneficiary 表示指定 A 为受益人；if 引导条件从句。','姐姐被指定在保单触发后领取保险金，对应法律/保单受益人义。')],mistakes:[m('The beneficiary of the will was the person who wrote it and gave no one any property.','The beneficiary of the will was the person who received property under it.','遗嘱受益人是取得遗产的人，不是未获财产的立遗嘱人。')],quiz:[q('beneficiary',1,1,'A beneficiary named in a will is someone who?','receives money or property under the will','writes every clause as a lawyer','witnesses the signature but receives nothing by definition','遗嘱受益人可从遗嘱中获得财产。'),q('beneficiary',2,2,'The main beneficiaries of a training program are?','the people the program helps','the machines used to teach','the officials who close the program','项目 beneficiaries 是受到项目帮助的人。'),q('beneficiary',3,3,'In legal usage, a beneficiary owner is?','an owner entitled to benefits under a legal arrangement','a person who owes every benefit to another','a clerk who files unsigned forms','法律文件中的 beneficiary 可形容享有收益者/所有者。'),q('beneficiary',4,1,'Which verb naturally goes with beneficiary?','name someone as a beneficiary','beneficiary someone into a house','beneficiary to receive someone','常见结构是 name someone as beneficiary。')]});
D('bent',{etymology:e('bent 是 bend 的古老过去分词形式；“弯曲的”直接承接 bend，“倾向、爱好”由弯向某方向的比喻发展，“决心做某事”见 be bent on。',src('bent')),contexts:[c('bent.s3','个人计划','After years of saving for a studio, Mina was bent on opening it before the summer festival, even if she had to finish the renovations herself.','米娜多年存钱想开工作室，因此决心在夏季节庆前开业，即使得自己完成装修也在所不惜。','After years of saving for a studio / Mina was bent on opening it before the summer festival / even if she had to finish the renovations herself.','be bent on + 名词或动名词表示下定决心；opening 作介词 on 的宾语。','她坚定计划开业，使用决心义 s3。')],mistakes:[m('He is bent on abandoning the project, so he has committed himself to finishing it this week.','He is bent on finishing the project, so he has committed himself to finishing it this week.','后半句显示他决心完成，而非放弃；将 abandoning 改为 finishing。')],quiz:[q('bent',1,1,'A person with a bent for music has?','a natural liking or talent for it','a broken musical instrument','a firm plan to stop listening','名词义 bent 可指爱好或天赋。'),q('bent',2,2,'A bent nail is?','curved rather than straight','sharper than a new nail','made from soft cloth','形容词 bent 指弯曲的。'),q('bent',3,3,'“She is bent on winning” means she?','is firmly determined to win','has already forgotten the contest','is physically curved over a table','be bent on 表示决心做某事。'),q('bent',4,1,'Which phrase uses bent as a noun meaning inclination?','a bent for engineering','a bent metal rod','bent on leaving','a bent for 表示对某事的爱好或倾向。')]});
D('beret',{etymology:e('英语 beret 借自法语 béret，后者经加斯科涅语与晚期拉丁语 birretum“帽子”有关；英语指无帽檐的圆扁软帽。',src('beret')),contexts:[c('beret.s1','服饰','Before stepping into the chilly courtyard, the painter pulled a wool beret over her hair and tucked the loose edge above one ear.','走进寒冷的院子前，画家把羊毛贝雷帽戴在头上，并把一侧松开的帽边掖到耳朵上方。','Before stepping into the chilly courtyard / the painter pulled a wool beret over her hair / and tucked the loose edge above one ear.','pull a beret over one’s hair 描述戴帽动作；wool 作材料定语。','圆软、无帽檐的帽子对应 beret 的词条义。')],mistakes:[m('He wore a beret with a long rigid peak projecting over his eyes.','He wore a cap with a long rigid peak projecting over his eyes.','beret 没有帽檐；带硬质长帽檐的头饰应称 cap。')],quiz:[q('beret',1,1,'A beret is usually?','a round soft cap without a peak','a tall hard hat with a visor','a scarf tied around the neck','beret 是圆扁、无帽檐的软帽。'),q('beret',2,1,'Which material commonly makes a beret?','wool or felt','window glass','woven steel wire','贝雷帽常用羊毛或毡制成。'),q('beret',3,1,'Choose the item a painter might wear.','a black beret','a beret with a rigid projecting peak','a beret worn as a shoe','画家常见的贝雷帽是软而无檐的帽子。'),q('beret',4,1,'Beret entered English from?','French','Mandarin','Icelandic','beret 是法语借词。')]});
D('berg',{etymology:e('berg 是英语借自德语 Berg“山”的词，英语航海用法常作 iceberg 的缩短形式，指从冰川断裂后漂浮的巨大冰块。',src('berg')),contexts:[c('berg.s1','海上航行','The lookout spotted a berg in the fog and radioed the bridge, giving the captain time to steer the vessel into open water.','瞭望员在雾中发现一座冰山并通知驾驶台，让船长有时间把船驶向开阔水域。','The lookout spotted a berg in the fog / and radioed the bridge / giving the captain time to steer the vessel into open water.','spot a berg 表示发现漂浮冰体；giving 短语说明报告带来的结果。','船只需要绕行的漂浮大冰块即 berg 的航海义。')],mistakes:[m('The ship avoided the berg, a small stone lying on the dry road.','The ship avoided the berg, a large mass of floating ice.','berg 指漂浮冰块而非路面小石头；修正同位语说明。')],quiz:[q('berg',1,1,'A ship changes course to avoid a berg because it is?','a floating mass of ice','a shallow pool of fresh water','a wooden mast','berg 在航海语境中指冰山。'),q('berg',2,1,'The English word berg is also connected with German for?','mountain','forest','harbor','德语 Berg 意为山。'),q('berg',3,1,'Which phrase is natural?','a berg floating beyond the ice shelf','a berg parked beside the curb','a berg flowering in spring','berg 的词条义是漂浮的大块冰。'),q('berg',4,1,'A berg broke away from a?','glacier','desert dune','brick wall','冰山从冰川断裂形成。')]});
D('bergere',{etymology:e('英语 bergère 借自法语，字面原指“牧羊女”；家具名用于一种法式扶手椅，名称沿用法语家具术语。',src('bergere')),contexts:[c('bergere.s1','古董家具','The restorer examined the bergere’s padded back and woven cane sides before replacing the worn seat fabric with a close match.','修复师检查了这把法式围手椅的软垫靠背和藤编侧面，然后用近似面料替换磨损的座垫。','The restorer examined the bergere’s padded back and woven cane sides / before replacing the worn seat fabric / with a close match.','所有格 bergere’s 修饰 back；before replacing 表示更换前先检查。','软垫靠背和藤编扶手侧板对应 bergere 家具义。')],mistakes:[m('They ordered a bergere, a narrow flat hat with no arms or back.','They ordered a beret, a narrow flat hat with no arms or back.','无帽檐软帽是 beret；bergere 是扶手椅，原句将家具与帽子混淆。')],quiz:[q('bergere',1,1,'A bergere is a type of?','French-style armchair','soft round cap','small fishing boat','bergere 指法式围手椅。'),q('bergere',2,1,'Which feature is typical of a bergere?','a padded back with cane or upholstered sides','a pointed roof and chimney','a wheel that pumps air','藤编侧面与软垫靠背是典型特征。'),q('bergere',3,1,'A furniture restorer might repair a bergere by?','replacing worn seat fabric','sharpening its blade','adding a bicycle chain','修复师会处理椅面面料。'),q('bergere',4,1,'Bergere was borrowed into English from?','French','Arabic','Korean','家具词 bergere 源自法语。')]});
D('Berlin',{etymology:e('Berlin 作为地名专名，其更早来源存在争议，此处不臆断词根；英语 Berlin wool 是以德国首都命名的历史毛线名称。',src('Berlin')),contexts:[c('Berlin.s1','城市地理','The delegation arrived in Berlin a day early, leaving time to visit the museum district before the climate conference began.','代表团提前一天抵达柏林，因此在气候会议开始前有时间参观博物馆区。','The delegation arrived in Berlin a day early / leaving time to visit the museum district / before the climate conference began.','城市专名 Berlin 首字母大写；arrive in 用于较大的城市或国家。','语境明确使用德国首都名，符合 s1。')],mistakes:[m('Berlin is the capital of France, and the delegation flew there from Lyon.','Berlin is the capital of Germany, and the delegation flew there from Lyon.','Berlin 是德国首都而非法国首都；仅更正国家名称。')],quiz:[q('Berlin',1,1,'Berlin is the capital of?','Germany','France','Austria','Berlin 是德国首都。'),q('Berlin',2,2,'The older expression Berlin wool referred to?','a soft wool yarn','a type of concrete','a German railway ticket','Berlin wool 是历史上的软毛线名称。'),q('Berlin',3,1,'Which sentence uses Berlin as the city name?','The conference will meet in Berlin.','She knitted with Berlin wool.','He bought a ball of yarn called Berlin.','首都城市义用于“会议在柏林举行”。'),q('Berlin',4,1,'Which spelling is correct for Germany’s capital?','Berlin','Berlyn','Berlinn','城市专名标准拼写为 Berlin。')]});
D('bespeak',{etymology:e('古英语 besprecan 由 be- + sprecan“说”构成，早期曾有“谈论、要求”义；现代常用义包括显示某特质，以及旧式的预先订下。',src('bespeak')),contexts:[c('bespeak.s1','人物评价','The careful footnotes in the report bespeak years of fieldwork, although the author gives no personal account of the research.','报告中谨慎的脚注显示作者多年实地研究的积累，尽管作者没有讲述个人研究经历。','The careful footnotes in the report bespeak years of fieldwork / although the author gives no personal account of the research.','bespeak 作及物动词，主语是迹象，宾语是所显示的事实；although 引导让步。','脚注显示长期研究，使用“表明、显示”义 s1。')],mistakes:[m('The neat, detailed records bespeak years of careful work, but they prove that no work was done.','The neat, detailed records bespeak years of careful work, and they show that much work was done.','精细记录显示投入劳动，不能证明毫无劳动；将结论改成相符内容。')],quiz:[q('bespeak',1,1,'A well-repaired bridge may bespeak?','careful maintenance','a complete lack of inspection','a plan to remove every support','bespeak 可指显示某事实或品质。'),q('bespeak',2,2,'To bespeak a carriage in older usage was to?','reserve or order it in advance','criticize the driver after the trip','measure the road width','旧式动词义 bespeak 可表示预订。'),q('bespeak',3,1,'Which sentence uses the “indicate” sense?','Her steady hands bespeak long experience.','He bespoke a taxi for dawn.','The hands bespeak to the clock.','steady hands 是经验的迹象，bespeak 表示显示。'),q('bespeak',4,1,'Which object can naturally bespeak confidence?','a calm, direct answer','a blank page never shown to anyone','a broken cup with no context','答复的方式可显示说话者的信心。')]});
D('bestow',{etymology:e('古英语 bestowian 源于 be- + stow“放置、安置”；从“放到某人身上/手中”发展为正式授予或慷慨给予。',src('bestow')),contexts:[c('bestow.s2','医疗照护','The nurses bestowed patient attention on every family, explaining the treatment plan twice when relatives needed time to absorb the news.','护士们耐心照顾每个家庭；亲属需要时间消化消息时，她们会把治疗计划解释两遍。','The nurses bestowed patient attention on every family / explaining the treatment plan twice / when relatives needed time to absorb the news.','bestow attention/care on someone 是“给予某人关注/照料”的搭配。','照护者给予时间和关怀，对应 s2 的注意与照料义。')],mistakes:[m('The committee bestowed the award on no one, yet presented the medal to Maya at the ceremony.','The committee bestowed the award on Maya and presented her with the medal at the ceremony.','颁奖给 Maya 与“没有授予任何人”矛盾；bestow A on B 表示正式授予。')],quiz:[q('bestow',1,1,'To bestow a medal on an athlete is to?','formally give the medal to the athlete','take the medal away secretly','describe the medal’s color only','bestow 可正式授予荣誉或奖章。'),q('bestow',2,2,'A parent may bestow care on a child by?','giving the child generous attention','ignoring every request','charging for each conversation','bestow 也可指给予关怀或关注。'),q('bestow',3,1,'Choose the standard pattern.','bestow an honor on the winner','bestow the winner an honor at','bestow to an honor the winner','常见结构是 bestow A on/upon B。'),q('bestow',4,1,'Which phrase uses bestow naturally?','bestow praise on the team','bestow the team from praise','bestow praise into the team','praise 可作为所给予的赞扬。')]});
D('betoken',{etymology:e('古英语 betacnian 由 be- + tacen“标记、征兆”构成；现代 betoken 是较正式的动词，意为预示或表明。',src('betoken')),contexts:[c('betoken.s1','天气观察','A sudden drop in pressure and a ring around the moon betokened a storm, so the crew secured the equipment before nightfall.','气压骤降和月晕预示暴风雨将至，因此船员在天黑前固定好设备。','A sudden drop in pressure and a ring around the moon betokened a storm / so the crew secured the equipment before nightfall.','两个并列主语共用过去式 betokened；so 引出根据征兆采取的结果。','气压和月晕被用作风暴到来的征兆，符合 s1。')],mistakes:[m('The clear, calm sky betokened a storm that had already passed, while no storm was approaching.','The darkening, unsettled sky betokened a storm that was approaching.','平静晴朗且风暴已过，与“预示风暴将来”不符；修正征兆与时间。')],quiz:[q('betoken',1,1,'Dark clouds at dusk may betoken?','a coming storm','a storm that happened centuries ago','a clear sky tomorrow with certainty','betoken 指预示将发生的事情。'),q('betoken',2,1,'A formal letter of thanks may betoken?','gratitude','a broken machine','a change in the alphabet','信件可表明寄信人的感激。'),q('betoken',3,1,'Choose the closest synonym in “The silence betokened unease.”','indicated','prevented','borrowed','betoken 在此可换作 indicated。'),q('betoken',4,1,'Which phrase is natural?','a sign that betokens trouble','a sign that betokens to trouble','a sign betokening of trouble','betoken 可直接接所预示的事物作宾语。')]});
D('betrayal',{etymology:e('betrayal 由 betray + 名词后缀 -al 构成，指背叛、泄露信任或出卖同伴的行为；betray 经古法语及中古英语进入现代形式。',src('betrayal')),contexts:[c('betrayal.s1','信任关系','When the editor published a confidential message without permission, her colleague saw the disclosure as a betrayal of the trust they had built over years.','编辑未经许可刊出机密信息后，同事把这次泄露视为对多年信任的背叛。','When the editor published a confidential message without permission / her colleague saw the disclosure as a betrayal of the trust / they had built over years.','see A as a betrayal of B 表示把某行为视作对 B 的背叛；过去完成时说明信任先于泄露建立。','未经同意泄露私信破坏信任，符合背叛义。')],mistakes:[m('Sharing her private letter with the public was a betrayal, so she carefully kept it confidential.','Sharing her private letter with the public was not a betrayal, because she had given permission.','如果本人已授权公开，泄露就不构成背叛；明确许可后需否定 betrayal。')],quiz:[q('betrayal',1,1,'A betrayal of trust is an act that?','breaks someone’s confidence','rewards someone for loyalty','keeps a promise exactly','betrayal 指破坏信任的行为。'),q('betrayal',2,1,'Which action could be called a betrayal?','handing a friend’s secret to their rival','returning a lost wallet','keeping a private promise','向对立者出卖秘密是背叛。'),q('betrayal',3,1,'Choose the correct noun: “She felt deeply hurt by the ___.”','betrayal','betray','betraying','the 后需名词 betrayal。'),q('betrayal',4,1,'Betrayal is most closely connected with?','a breach of trust','a routine greeting','a fair exchange of gifts','该名词的核心是背叛信任。')]});
D('bewail',{etymology:e('中古英语 bewailen 由 be- + wail“哀号、痛哭”构成，作及物动词表示为损失或不幸哀叹、痛惜。',src('bewail')),contexts:[c('bewail.s1','文化遗产','Local historians bewail the demolition of the old station, whose iron roof had sheltered generations of travelers from the rain.','当地历史学家痛惜旧车站被拆除；那座车站的铁顶曾为几代旅客遮风挡雨。','Local historians bewail the demolition of the old station / whose iron roof had sheltered generations of travelers from the rain.','bewail 是及物动词，直接接被痛惜的事；whose 引导定语从句。','历史学家为车站拆除而惋惜，符合哀叹义。')],mistakes:[m('Residents bewail the reopening of the beloved park and celebrate that it is available again.','Residents welcome the reopening of the beloved park and celebrate that it is available again.','庆祝公园重新开放不是痛惜；将 bewail 换成 welcome 与后文相合。')],quiz:[q('bewail',1,1,'A person who bewails a loss?','expresses grief about it','claims it never happened','celebrates it with a party','bewail 指为损失悲叹。'),q('bewail',2,1,'Which event might a community bewail?','the destruction of a historic bridge','the successful repair of the bridge','a new bridge opening on schedule','社区会为历史桥梁被毁而惋惜。'),q('bewail',3,1,'Choose the correct form: “Critics ___ the loss of the old theater.”','bewail','bewails','bewailing to','复数主语 critics 后用原形 bewail。'),q('bewail',4,1,'Bewail is closest in meaning to?','lament','approve','measure','lament 是“哀叹、痛惜”的近义词。')]});
D('bewildering',{etymology:e('bewildering 是 bewilder + -ing 构成的形容词；bewilder 与 be- 和 wilder（使迷失、使无所适从）相关，现代意为令人困惑的。',src('bewildering')),contexts:[c('bewildering.s1','办事流程','The online form presented a bewildering list of nearly identical categories, so applicants kept selecting the wrong permit type.','在线表格列出一长串几乎相同的类别，令人眼花缭乱，申请者因此不断选错许可证类型。','The online form presented a bewildering list of nearly identical categories / so applicants kept selecting the wrong permit type.','bewildering 作形容词修饰 list；keep doing 表示反复发生。','选项太多且相似，使人不知所措，对应词条义。')],mistakes:[m('The simple two-step form was bewildering because every choice was clearly labeled and easy to follow.','The dense, confusing form was bewildering because its choices were difficult to distinguish.','标签清楚、步骤简单通常不会令人困惑；改为选项难分辨以符合 bewildering。')],quiz:[q('bewildering',1,1,'A bewildering set of choices is?','so confusing that it is hard to decide','so simple that no thought is needed','small enough to fit in a pocket','bewildering 表示令人困惑、不知所措。'),q('bewildering',2,1,'A bewildering map might have?','too many unclear routes and symbols','one clear route to the station','no roads or labels at all but no task','路线标记繁杂不清会让人困惑。'),q('bewildering',3,1,'Which phrase is natural?','a bewildering array of plans','a bewildering clearly obvious answer','a bewilderingly plan','bewildering 可修饰 array，表示种类繁多而难辨。'),q('bewildering',4,1,'The adjective bewildering describes something that?','causes confusion','removes all uncertainty','is physically curved','bewildering 的核心是令人困惑。')]});
D('bewitch',{etymology:e('中古英语 bewitchen 由 be- + witch 构成，字面与“施以巫术”有关；后来也比喻强烈吸引、迷住某人。',src('bewitch')),contexts:[c('bewitch.s1','音乐演出','The violinist’s quiet opening gradually bewitched the audience, and by the final movement even the restless children sat still.','小提琴手安静的开场逐渐迷住了观众；到最后一个乐章时，连坐不住的孩子也静了下来。','The violinist’s quiet opening gradually bewitched the audience / and by the final movement / even the restless children sat still.','bewitch 作及物动词，audience 是被吸引的人；by 表示到某一时点。','音乐使观众全神贯注，使用比喻义“迷住”s1。')],mistakes:[m('The dull lecture bewitched the audience, and everyone immediately left because they found it fascinating.','The dull lecture bored the audience, and everyone immediately left because they found it tedious.','发现演讲乏味并离场与“被迷住”相矛盾；将动词改为 bored。')],quiz:[q('bewitch',1,1,'A performance that bewitches its audience?','holds them strongly through its charm','makes them lose their tickets','forces them to do arithmetic','bewitch 比喻强烈吸引、迷住观众。'),q('bewitch',2,2,'In a story, a witch may bewitch a well by?','putting it under a supposed spell','repairing its stone lining','measuring its depth','bewitch 的字面义可指施魔法。'),q('bewitch',3,1,'Which sentence uses the figurative sense?','The dancer’s grace bewitched the crowd.','The crowd bewitch to the dancer’s grace.','The dancer was a bewitched audience.','优雅的舞姿迷住观众，是比喻用法。'),q('bewitch',4,1,'Choose the natural pattern.','bewitch someone with a melody','bewitch to someone with melody','bewitched someone of melody','可说用旋律迷住某人，bewitch someone with ...。')]});
D('biannual',{etymology:e('biannual 由 bi-“两次”与 annual“每年的”组合，按本词条指一年发生两次；为避免与 biennial“一年一次、两年一次”混淆，应明确频率。',src('biannual')),contexts:[c('biannual.s1','审计安排','The board holds a biannual review in April and October, so each report covers six months of spending rather than a full year.','董事会每年四月和十月各举行一次审查，因此每份报告涵盖半年开支，而不是整年。','The board holds a biannual review in April and October / so each report covers six months of spending / rather than a full year.','biannual 修饰 review；April and October 明确是同一年内两次。','两个日期相隔半年，锁定一年两次义，避免按词根误解频率。')],mistakes:[m('The biannual safety inspection takes place only once every two years, in April.','The biennial safety inspection takes place only once every two years, in April.','一年一次/两年一次应用 biennial；本条 biannual 指每年两次。')],quiz:[q('biannual',1,1,'A biannual meeting held in March and September occurs?','twice in one year','once every two years','every two months','词条把 biannual 明确限定为一年两次。'),q('biannual',2,1,'Which schedule is biannual?','reviews in April and October each year','one review every other year','a review every week','同一年两个不同时间举行即一年两次。'),q('biannual',3,1,'Which word usually means once every two years?','biennial','biannual','annual','biennial 通常表示每两年一次。'),q('biannual',4,1,'A biannual report covering six months is issued?','twice each year','every ten years','only after two decades','半年一份报告意味着每年两次。')]});
D('bicameral',{etymology:e('英语 bicameral 由拉丁语 bi-“两个”与 camera“房间、议事厅”加 -al 构成，常指立法机关由两个院组成。',src('bicameral')),contexts:[c('bicameral.s1','宪政','The constitution established a bicameral parliament, requiring both the lower house and the senate to approve the budget before it became law.','宪法设立两院制议会，要求预算成为法律前同时获得下议院和参议院通过。','The constitution established a bicameral parliament / requiring both the lower house and the senate to approve the budget / before it became law.','bicameral 修饰 parliament；both ... and ... 并列两个院；requiring 表示制度要求。','议会由下议院和参议院两个部分构成，符合 s1。')],mistakes:[m('The country has a bicameral legislature with one single chamber, and no second house.','The country has a unicameral legislature with one single chamber, and no second house.','只有一个院应称 unicameral；bicameral 要求两院。')],quiz:[q('bicameral',1,1,'A bicameral parliament has?','two legislative chambers','one legislative chamber','no elected representatives','bi- 加 chamber 意味着两个议事院。'),q('bicameral',2,2,'A committee described as bicameral is made up of?','two chambers or groups','one member only','four unrelated courts','词条第二义泛指由两个议事部分组成。'),q('bicameral',3,1,'A legislature with only one house is?','unicameral','bicameral','bilateral','unicameral 才指一院制。'),q('bicameral',4,1,'Which combination could form a bicameral legislature?','a lower house and a senate','one mayor and one courthouse','two copies of the same ballot','两个立法机构组成两院制。')]});

/* A9 checkpoint 3/4: entries 41–60. */
D('bicentennial',{etymology:e('bicentennial 由 bi-“二”与 centennial“百年纪念”构成，指满两百年的纪念或纪念年份；centennial 追溯拉丁语 centum“百”与 annus“年”。',src('bicentennial')),contexts:[c('bicentennial.s1','城市庆典','For the town’s bicentennial, the museum displayed the original charter beside photographs showing how the main street had changed over two centuries.','为庆祝该镇建镇二百周年，博物馆把原始特许状与展示主街两百年变迁的照片并列展出。','For the town’s bicentennial / the museum displayed the original charter beside photographs / showing how the main street had changed over two centuries.','town’s bicentennial 表示建镇二百周年；how 引导宾语从句。','庆祝两百年历史里程碑，符合二百周年义。')],mistakes:[m('The town marked its bicentennial after only one hundred years had passed since its founding.','The town marked its centennial after one hundred years had passed since its founding.','建镇一百周年是 centennial；bicentennial 需要两百年。')],quiz:[q('bicentennial',1,1,'A bicentennial marks?','two hundred years since an event','one hundred days since an event','twenty years since an event','bi- + centennial 指二百周年。'),q('bicentennial',2,1,'A city celebrates its bicentennial in 2026. It was founded around?','1826','1926','2025','二百周年表示比纪念年早约两百年。'),q('bicentennial',3,1,'Which celebration is bicentennial?','a school’s 200th anniversary','a company’s 100th anniversary','a club’s 20th meeting','满两百年的纪念才是 bicentennial。'),q('bicentennial',4,1,'The element centennial refers to a period of?','one hundred years','ten months','one thousand days','centennial 涉及一百年，前加 bi- 得二百年。')]});
D('bidder',{etymology:e('bidder 是英语 bid 加施事者后缀 -er，指在拍卖中出价或参与工程投标的人或机构。',src('bidder')),contexts:[c('bidder.s1','拍卖会','The highest bidder won the antique map after raising her offer twice, while the other participants stopped when the price passed their limits.','最高出价者两次提高报价后拍下古地图；价格超过其他人的上限时，他们便停止竞价。','The highest bidder won the antique map / after raising her offer twice / while the other participants stopped / when the price passed their limits.','bidder 作可数名词；raise an offer 表示提高出价，最高者赢得拍品。','买家通过竞拍出价取得拍品，符合 bidder 义。')],mistakes:[m('The winning bidder never made an offer, but was selected because another person offered the highest price.','The winning bidder made the highest offer and was selected to buy the map.','没有出价的人不能凭自己的竞价获胜；修正为 bidder 提出最高报价。')],quiz:[q('bidder',1,1,'At an auction, a bidder is someone who?','offers a price for an item','repairs the auction room','writes the item’s history','bidder 指在拍卖中出价者。'),q('bidder',2,1,'A company submitting a construction tender can be called a?','bidder','bellows','belle','递交投标报价的公司也是 bidder。'),q('bidder',3,1,'Which person is the highest bidder?','the person who offers the most money','the person who arrives first','the person who describes the painting','最高出价者的金额最高。'),q('bidder',4,1,'The suffix -er in bidder identifies?','a person or party that bids','the past tense of bid','a tool used to count bids','-er 可构成执行 bid 动作的人。')]});
D('bidding',{etymology:e('bidding 是 bid + -ing 的名词形式；英语 bid 源自古英语 biddan，含“请求、命令”义，现代 bidding 可指出价活动或某人的吩咐。',src('bidding')),contexts:[c('bidding.s2','服从吩咐','The assistant carried out the director’s bidding and delivered the sealed envelope before the office closed.','助理照导演的吩咐行事，在办公室关门前送出了密封信封。','The assistant carried out the director’s bidding / and delivered the sealed envelope / before the office closed.','do/carry out someone’s bidding 表示照某人吩咐办事；before 引导时间状语。','这里表示服从上级的命令，对应 s2，不是拍卖出价。')],mistakes:[m('The servant refused to do the king’s bidding, so he obeyed every command immediately.','The servant did the king’s bidding, so he obeyed every command immediately.','“refused”与后文“服从每道命令”矛盾；改为 did the bidding。')],quiz:[q('bidding',1,1,'At an auction, bidding is?','the process of making offers to buy','the process of painting the item','the final delivery of a purchased item','拍卖义 bidding 是竞价过程。'),q('bidding',2,2,'To do someone’s bidding is to?','carry out that person’s commands','ask them to lower a price','refuse every request they make','固定表达指按某人吩咐行事。'),q('bidding',3,1,'The bidding starts at $500. What is happening?','buyers are making offers','the auctioneer is delivering the item','the seller is repairing a table','竞价从五百美元起开始。'),q('bidding',4,2,'Which phrase uses bidding for “command”?','at the general’s bidding','the bidding rose by ten dollars','bidding began when the lot opened','at someone’s bidding 指奉其命令行事。')]});
D('bifocal',{etymology:e('bifocal 由 bi-“两个”与 focal“焦点的”组成，focal 与 focus 同源；眼镜的双焦设计通常让佩戴者分别看远处和近处。',src('bifocal')),contexts:[c('bifocal.s1','视力矫正','Because he needed one prescription for driving and another for reading, the optician fitted Mr. Wu with bifocal lenses divided into near and distance zones.','由于开车和阅读需要不同度数，验光师给吴先生配了双焦镜片，分为近用和远用区域。','Because he needed one prescription for driving and another for reading / the optician fitted Mr. Wu with bifocal lenses / divided into near and distance zones.','bifocal 修饰 lenses；divided 过去分词短语描述镜片分区。','同一镜片有两种光学度数，符合双焦义。')],mistakes:[m('Her bifocal lenses had three separate optical powers for near, middle, and far vision.','Her trifocal lenses had three separate optical powers for near, middle, and far vision.','三种焦距是 trifocal；bifocal 表示两种焦距。')],quiz:[q('bifocal',1,1,'Bifocal lenses are designed with?','two optical strengths','one strength for every distance','three separate optical zones','bi- 表示二，双焦镜片有两种度数。'),q('bifocal',2,1,'Which wearer might choose bifocals?','someone needing help with both near and far vision','someone who needs hearing protection','someone whose glasses have no lenses','双焦镜片常兼顾看近和看远。'),q('bifocal',3,1,'The “bi-” in bifocal means?','two','one hundred','without','bi- 表示两个。'),q('bifocal',4,1,'An optician might divide a bifocal lens into zones for?','reading and distance viewing','left and right ears','day and night sounds','双焦镜片分别矫正近视阅读与远视距离需求。')]});
D('bigoted',{etymology:e('bigoted 是 bigot 加 -ed 构成的形容词，表示抱有顽固偏见或歧视；bigot 的更早词源并无定论，这里不臆造词根。',src('bigot')),contexts:[c('bigoted.s1','公共言论','The moderator removed a bigoted post that blamed an entire religious group for one person’s crime and invited readers to report similar abuse.','版主删除了一则把个人罪行归咎于整个宗教群体的偏见言论，并请读者举报类似辱骂。','The moderator removed a bigoted post / that blamed an entire religious group for one person’s crime / and invited readers to report similar abuse.','bigoted 修饰 post；that 从句说明帖文的偏见内容。','把个体罪行归咎于整个宗教群体体现歧视性偏见，符合 s1。')],mistakes:[m('The fair-minded chair listened to every group equally, a bigoted approach that excluded no one.','The fair-minded chair listened to every group equally, an impartial approach that excluded no one.','公平倾听所有群体并非偏见做法；将 bigoted 改为 impartial。')],quiz:[q('bigoted',1,1,'A bigoted remark about a religion expresses?','an unfair prejudice against a group','a neutral description of a ceremony','a measurement of a building','bigoted 指基于群体身份的偏见。'),q('bigoted',2,2,'Someone who is bigoted in the sense of being obstinate?','refuses to reconsider unreasonable beliefs','changes an opinion after seeing evidence','asks others to explain a view','bigoted 也可泛指顽固坚持不合理信念。'),q('bigoted',3,1,'Which action is most clearly bigoted?','excluding applicants solely because of their ethnicity','comparing applicants’ relevant experience','asking all candidates the same question','按族裔排斥申请者体现歧视。'),q('bigoted',4,1,'Choose the adjective: “The article contained ___ comments.”','bigoted','bigot','bigotingly','bigoted 是形容词，可修饰 comments。')]});
D('bike',{etymology:e('bike 是 bicycle 的口语缩略形式；英语中也常把 motorcycle 简称 bike，具体指自行车还是摩托车需依语境判断。',src('bike')),contexts:[c('bike.s2','交通','After the rain stopped, Amir parked his bike outside the workshop, removed his helmet, and checked the motorcycle’s rear tire.','雨停后，阿米尔把摩托车停在修理铺外，摘下头盔并检查后轮胎。','After the rain stopped / Amir parked his bike outside the workshop / removed his helmet / and checked the motorcycle’s rear tire.','bike 前的 helmet 以及 motorcycle 明确限定为摩托车义 s2。','戴头盔并检查摩托车后胎说明这里 bike 指摩托车。')],mistakes:[m('She pedaled her bike down the hill, although it had an engine and she was riding it as a motorcycle.','She rode her bike down the hill, although it had an engine and she was riding it as a motorcycle.','有发动机的摩托车不是脚踏车，不能说 pedaled；改用 ride。')],quiz:[q('bike',1,1,'A child pedals a bike through the park. The bike is a?','bicycle','motorcycle','bus','pedal 说明 bike 指自行车。'),q('bike',2,2,'In “He put on a helmet before riding his bike,” bike may mean?','motorcycle','unicycle only','shopping cart','头盔和 riding 提示口语摩托车义。'),q('bike',3,1,'Bike is commonly shortened from which word?','bicycle','biography','bidding','bike 常由 bicycle 缩略而来。'),q('bike',4,2,'Which clue most strongly suggests motorcycle?','an engine and a riding helmet','pedals and a small bell','a basket on the handlebars','发动机与骑行头盔提示摩托车。')]});
D('bilingual',{etymology:e('英语 bilingual 源自拉丁语 bilinguis，由 bi-“两个”与 lingua“语言”组成；形容会说两种语言的人，也可修饰以两种语言书写或教学的材料。',src('bilingual')),contexts:[c('bilingual.s2','公共服务','The clinic installed bilingual signs in English and Spanish so that patients could find the pharmacy and emergency exit without asking for help.','诊所在公共区域安装英语和西班牙语双语标识，使患者无需求助也能找到药房和紧急出口。','The clinic installed bilingual signs in English and Spanish / so that patients could find the pharmacy and emergency exit / without asking for help.','bilingual 修饰 signs；in + 两种语言列出标识使用的语言。','标识使用两种语言而非描述会说两种语言的人，符合 s2。')],mistakes:[m('The bilingual notice was printed only in English, with no second language anywhere on the page.','The monolingual notice was printed only in English, with no second language anywhere on the page.','只用一种语言应称 monolingual；bilingual 要求两种语言。')],quiz:[q('bilingual',1,1,'A bilingual employee can?','speak two languages well','speak no language at all','translate only numbers into music','bilingual 可形容能讲两种语言的人。'),q('bilingual',2,2,'A bilingual sign is written?','in two languages','in two different typefaces only','without any words','双语标识用两种语言书写。'),q('bilingual',3,1,'The Latin element bi- means?','two','one','many hundreds','bi- 表示两个。'),q('bilingual',4,2,'Which is a bilingual service?','instructions offered in English and Spanish','an English-only leaflet with two fonts','a silent display with no text','两种语言提供的说明服务是双语服务。')]});
D('bilingualism',{etymology:e('bilingualism 由 bilingual + -ism 构成，指个人使用两种语言的能力，也可指学校或社会中双语并用的现象。',src('bilingualism')),contexts:[c('bilingualism.s1','边境社区','Bilingualism is common in the border district, where public offices issue forms in both languages and children hear each one at home.','边境地区常见双语并用，公共机构用两种语言发放表格，孩子在家也会听到这两种语言。','Bilingualism is common in the border district / where public offices issue forms in both languages / and children hear each one at home.','bilingualism 作主语；where 引导地点定语从句。','语境描述一个地区普遍使用两种语言，符合社会现象义 s1。')],mistakes:[m('The town’s bilingualism means its schools forbid every language except one.','The town’s monolingualism means its schools forbid every language except one.','只允许一种语言与双语现象相反；应改为 monolingualism。')],quiz:[q('bilingualism',1,1,'Bilingualism in a region refers to?','the use of two languages in that community','the loss of all spoken languages','the use of one alphabet by itself','社会层面指两种语言共同使用。'),q('bilingualism',2,2,'A person’s bilingualism is their?','ability to use two languages','ability to speak twice as loudly','knowledge of two unrelated alphabets only','个人层面指掌握两种语言的能力。'),q('bilingualism',3,1,'Which suffix turns bilingual into the name of a condition or system?','-ism','-ful','-less','-ism 构成 bilingualism 这一现象/状态名词。'),q('bilingualism',4,1,'A school with classes in two languages is an example of?','institutional bilingualism','a single-language policy','a spelling reform','学校双语授课体现制度层面的双语现象。')]});
D('billboard',{etymology:e('billboard 由 bill（张贴或刊登的告示）与 board（板）组成；作动词时表示在广告牌上大幅宣传某事物。',src('billboard')),contexts:[c('billboard.s1','道路广告','A bright billboard beside the highway announced the museum’s new exhibit, but the driver waited until the next exit to read the details safely.','高速公路旁一块醒目的广告牌宣布博物馆新展览；司机等到下一个出口才安全地看细节。','A bright billboard beside the highway announced the museum’s new exhibit / but the driver waited until the next exit / to read the details safely.','billboard 作主语；beside the highway 描述其位置，to read 表目的。','路边的大幅展示板是名词义 s1。')],mistakes:[m('The billboard was a small leaflet folded into the traveler’s pocket.','The brochure was a small leaflet folded into the traveler’s pocket.','口袋里的折页不是大型广告牌；改为 brochure 匹配体积与用途。')],quiz:[q('billboard',1,1,'A billboard is usually?','a large board displaying an advertisement','a private letter folded in an envelope','a small label sewn into a shirt','billboard 指大型广告展示板。'),q('billboard',2,2,'To billboard a concert means to?','advertise it on large outdoor boards','cancel it after tickets sell','write a private review after it ends','billboard 作动词指用广告牌宣传。'),q('billboard',3,1,'Where might a driver see a billboard?','beside a highway','inside a sealed medicine capsule','under a restaurant plate','大型广告牌常设在道路旁。'),q('billboard',4,2,'Choose the correct verb use.','The studio billboarded the tour across the city.','The studio bill boarded the tour politely.','The studio billboarded to tour the city.','billboard 作动词可直接接被宣传的活动作宾语。')]});
D('billfish',{etymology:e('复合词 bill + fish，bill 指鸟喙状的长突吻；billfish 是长嘴的大型掠食性海鱼总称，包括旗鱼和枪鱼等。',src('billfish')),contexts:[c('billfish.s1','海洋生物','The marine survey photographed a billfish near the reef, identifying it by the long pointed bill extending from its upper jaw.','海洋调查在礁石附近拍到一条长嘴鱼，并凭上颚延伸出的尖长吻部辨认出它。','The marine survey photographed a billfish near the reef / identifying it by the long pointed bill / extending from its upper jaw.','billfish 作可数名词；identifying 短语说明调查人员如何辨认。','长而尖的喙状上颚是长嘴鱼的辨认特征。')],mistakes:[m('A billfish is named for its round beakless mouth and is usually a small freshwater fish.','A billfish is named for its long bill-like snout and is usually a large predatory sea fish.','billfish 的关键特征是延长的喙状吻部，不是无喙小型淡水鱼。')],quiz:[q('billfish',1,1,'A billfish is recognized by its?','long bill-like snout','feathers around its neck','flat shell on its back','长嘴鱼的上颚延长成喙状。'),q('billfish',2,1,'Which pair are billfish?','marlin and sailfish','salmon and trout','crab and lobster','旗鱼与枪鱼都属于长嘴鱼。'),q('billfish',3,1,'In the compound billfish, bill refers to?','a beak-shaped projection','a payment invoice','a fish’s tail fin','bill 在这里指喙状吻部。'),q('billfish',4,1,'Billfish are generally?','large predatory marine fish','small garden insects','freshwater plants','词条定义为大型掠食性海鱼。')]});
D('binary',{etymology:e('英语 binary 借自拉丁语 binarius“成双的、每次两个”，与 bini“两个一组”相关；计算机义特指只用 0 和 1 表示数据。',src('binary')),contexts:[c('binary.s1','计算机编码','The sensor sends each measurement as binary code, translating every value into a sequence of zeros and ones before the processor stores it.','传感器把每次测量转换成二进制代码，在处理器存储前将每个数值编码为一串 0 和 1。','The sensor sends each measurement as binary code / translating every value into a sequence of zeros and ones / before the processor stores it.','binary 修饰 code；before 引导时间状语从句。','序列只使用两个数字 0 和 1，符合计算机义 s1。')],mistakes:[m('The binary system uses ten digits, from zero through nine, as its only symbols.','The decimal system uses ten digits, from zero through nine, as its symbols.','0 到 9 共十个数字是十进制；binary 只用 0 和 1。')],quiz:[q('binary',1,1,'Binary computer code uses which digits?','0 and 1','1 through 9','all ten decimal digits','二进制只使用 0 与 1。'),q('binary',2,2,'A binary choice is a choice between?','two alternatives','exactly seven alternatives','no available alternatives','binary 也可泛指由两部分组成。'),q('binary',3,1,'Which number is written in binary notation?','1011','eight','nine','二进制表示法由 0、1 组成。'),q('binary',4,2,'A debate framed as a binary choice offers?','two categories or options','a continuous range with no divisions','four independent answers','binary choice 将选项划分为两类。')]});
D('binge',{etymology:e('英语 binge 约在19世纪口语中出现，常指短期内狂饮或过量行为；更早词源不确定，此处不臆造词根。',src('binge')),contexts:[c('binge.s1','健康习惯','After weeks of skipping meals, he had a late-night eating binge and felt sick, so he spoke with a counselor about a steadier routine.','连续几周不吃正餐后，他深夜暴食并感到不适，于是向辅导员咨询更规律的生活方式。','After weeks of skipping meals / he had a late-night eating binge and felt sick / so he spoke with a counselor / about a steadier routine.','eating binge 指一次短时过量进食；so 引出后续行动。','短时间内吃得过多，符合 binge 的过量行为义。')],mistakes:[m('She called it a binge because she ate one normal meal slowly and stopped when she was full.','She called it a regular meal because she ate one normal meal slowly and stopped when she was full.','正常进食并适时停下不构成短时放纵或狂吃；改为 regular meal。')],quiz:[q('binge',1,1,'An eating binge is?','a short period of eating far too much','a carefully portioned ordinary meal','a week-long fast with no food','binge 指一段时间内过量进食。'),q('binge',2,1,'A person may go on a spending binge by?','buying far more than intended in a short period','saving every coin for a year','returning all purchases immediately','binge 可指短期内过度购物等放纵行为。'),q('binge',3,1,'Which phrase is natural?','a weekend binge of television watching','a binge because she watched one short clip','binge to the weekend for television','binge 可与电视观看等活动连用。'),q('binge',4,1,'The word binge most strongly suggests?','excess over a limited period','a precise daily schedule','a permanent lack of interest','binge 强调短时间的过量。')]});
D('bingo',{etymology:e('bingo 是英语游戏名，源自玩家在卡片数字成行时喊出的胜利用语；该喊声作为游戏名称的更早形成细节不确定。',src('bingo')),contexts:[c('bingo.s1','社区活动','At the Friday fundraiser, volunteers called each number slowly while players covered matching squares on their bingo cards and waited to complete a row.','星期五的募款活动中，志愿者慢慢报出数字，玩家在宾戈卡上盖住对应格子，等待连成一行。','At the Friday fundraiser / volunteers called each number slowly / while players covered matching squares on their bingo cards / and waited to complete a row.','bingo 作不可数游戏名；while 表示报数与盖格同时发生。','数字卡片上盖中被叫号码的游戏是 bingo。')],mistakes:[m('They played bingo by rolling a ball into a goal while the caller read out football scores.','They played bingo by covering called numbers on their cards until a row was complete.','进球得分不是宾戈规则；改为卡片上覆盖被叫到的数字。')],quiz:[q('bingo',1,1,'In bingo, players usually?','cover numbers called on their cards','move chess pieces across a board','guess a hidden word from its spelling','玩家覆盖被叫出的数字。'),q('bingo',2,1,'A player often wins bingo by completing?','a required line or pattern','a marathon race','a jigsaw puzzle with no pieces','宾戈卡上通常按规则连成一行或图案。'),q('bingo',3,1,'Where might a community hold bingo?','in a village hall','inside a swimming lane','on a mountain climbing rope','宾戈常作为社区大厅里的活动。'),q('bingo',4,1,'The exclamation “Bingo!” is often called when?','a player completes the winning pattern','a card is left blank','the caller forgets every number','连成获胜图案时玩家会喊 bingo。')]});
D('biochemical',{etymology:e('biochemical 由 bio-“生物”与 chemical“化学的”构成，指生物体内或生命过程中涉及的化学反应与物质。',src('biochemical')),contexts:[c('biochemical.s1','细胞实验','The lab measured a biochemical reaction in the cell after adding the enzyme, then compared the results with an untreated sample.','实验室加入酶后测量细胞内的一种生化反应，再将结果与未处理样本比较。','The lab measured a biochemical reaction in the cell / after adding the enzyme / then compared the results with an untreated sample.','biochemical 修饰 reaction；after adding 表示加入酶之后。','细胞内的反应属于生命过程中的化学变化。')],mistakes:[m('A biochemical reaction happens only in a metal pipe and has no connection to any living organism.','A chemical reaction happens only in a metal pipe and has no connection to any living organism.','没有生命体参与的金属管道反应不能称为生物化学反应；去掉 bio-。')],quiz:[q('biochemical',1,1,'A biochemical process takes place in connection with?','living organisms and their chemistry','only the movement of planets','the grammar of a language','biochemical 指生物体内的化学过程。'),q('biochemical',2,1,'Which topic is biochemical?','how an enzyme changes a reaction in a cell','how a bridge carries traffic','how a poem uses rhyme','细胞与酶相关的反应属于生化研究。'),q('biochemical',3,1,'The prefix bio- relates to?','life','sound','writing','bio- 表示生命、生物。'),q('biochemical',4,1,'A biochemical signal is most likely studied by?','a biochemist','a cartographer','a music conductor','生化学家研究生物化学信号。')]});
D('biodiversity',{etymology:e('biodiversity 由 bio-“生命、生物”与 diversity“多样性”组合，指一个地区各种生物类型及其差异，也常用于生物多样性保护。',src('biodiversity')),contexts:[c('biodiversity.s2','保护规划','The reserve’s biodiversity program restored wetlands, replanted native grasses, and limited night lighting to protect insects, birds, and amphibians.','保护区的生物多样性项目修复湿地、重植本地草类，并限制夜间照明以保护昆虫、鸟类和两栖动物。','The reserve’s biodiversity program restored wetlands / replanted native grasses / and limited night lighting / to protect insects, birds, and amphibians.','biodiversity 修饰 program；三个并列动词说明保护行动。','语境讲保护多种生物及其栖息环境，符合保护义 s2。')],mistakes:[m('The biodiversity project removed native habitats and introduced one species everywhere, reducing the range of life in the reserve.','The biodiversity project restored native habitats and protected many species, increasing the range of life in the reserve.','破坏栖息地并只留一种生物会降低多样性，不是保护项目目标。')],quiz:[q('biodiversity',1,1,'A forest rich in biodiversity has?','many kinds of living organisms','only one species of tree','no living things at all','biodiversity 指生物种类的丰富程度。'),q('biodiversity',2,2,'Biodiversity conservation aims to?','protect varied forms of life','replace every species with one crop','remove habitats from a region','保护生物多样性旨在维护多种生命。'),q('biodiversity',3,1,'Which area likely has higher biodiversity?','a wetland with many native plants and animals','a sealed room with no organisms','a field planted with one crop only','多种本地生物共存说明多样性较高。'),q('biodiversity',4,1,'The element bio- refers to?','living things','stone tools','written records','bio- 与生物、生命有关。')]});
D('biogeochemical',{etymology:e('biogeochemical 由 bio-（生物）、geo-（地球/地质）和 chemical（化学）组成，指生物、地质、水与化学物质相互作用的过程或循环。',src('biogeochemical')),contexts:[c('biogeochemical.s1','碳循环','The diagram traced a biogeochemical cycle in which plants absorbed carbon, animals consumed the plants, and decomposition returned nutrients to the soil.','图示追踪一个生物地球化学循环：植物吸收碳，动物取食植物，分解过程又把养分还给土壤。','The diagram traced a biogeochemical cycle / in which plants absorbed carbon / animals consumed the plants / and decomposition returned nutrients to the soil.','biogeochemical 修饰 cycle；in which 引导说明循环过程的关系从句。','该循环涉及生物、土壤和化学元素流动，符合词义。')],mistakes:[m('A biogeochemical cycle concerns only the spelling of rocks, with no organisms or chemical movement.','A geological classification concerns the naming of rocks, whereas a biogeochemical cycle tracks interactions among life, Earth, and chemicals.','生物地球化学循环涉及物质和生命过程，不是单纯岩石命名。')],quiz:[q('biogeochemical',1,1,'A biogeochemical cycle involves interactions among?','living things, Earth materials, and chemicals','musical notes and dance steps','two chambers of a parliament','bio-, geo-, chemical 三部分指涉生命、地球与化学。'),q('biogeochemical',2,1,'The carbon cycle is an example of a?','biogeochemical cycle','bilingual schedule','bifocal lens','碳在生物、空气和土壤间循环，属于生物地球化学过程。'),q('biogeochemical',3,1,'Which field would study nutrients moving from soil into plants?','biogeochemistry','calligraphy','auction law','土壤与生物间的化学元素流动属于此领域。'),q('biogeochemical',4,1,'In biogeochemical, geo- points to?','Earth or geological systems','language ability','a courtroom order','geo- 表示地球或地质。')]});
D('biographer',{etymology:e('biographer 由 biography“传记”加施事者后缀 -er 构成；biography 追溯希腊语 bios“生命”与 graphein“写”。',src('biographer')),contexts:[c('biographer.s1','人物传记','The biographer interviewed the scientist’s former students, checked the laboratory notebooks, and revised a chapter when the dates did not match.','传记作者采访了科学家的昔日学生，核对实验记录，并在日期不符时修改章节。','The biographer interviewed the scientist’s former students / checked the laboratory notebooks / and revised a chapter / when the dates did not match.','biographer 是从事写作的人；三个并列过去式动词说明其工作。','采访并书写他人生平的人是传记作者。')],mistakes:[m('A biographer writes a person’s life story, but this biographer deliberately invented every date and ignored all evidence.','A novelist writes invented stories, while a biographer researches and writes a person’s life.','凭空编造不是传记写作的定义；用 novelist 区分虚构作者。')],quiz:[q('biographer',1,1,'A biographer writes about?','another person’s life','the rules of a board game','the design of a building','biographer 是为他人作传的人。'),q('biographer',2,2,'The biographer of a poet is?','the writer of that poet’s life story','the poet’s editor of every poem','a person who only sells poetry books','of a poet 表明传记作者写这位诗人的生平。'),q('biographer',3,1,'Which source might a biographer consult?','letters and diaries','a restaurant menu alone','a weather forecast unrelated to the person','书信日记可供传记作者研究生平。'),q('biographer',4,1,'The suffix -er in biographer marks?','a person who writes biographies','the adjective form of life','a book containing no words','-er 在此构成人物职业名词。')]});
D('biographic',{etymology:e('biographic 由 biography 的词干 biograph- 加形容词后缀 -ic 构成，指与人生经历或传记体裁有关；biographical 是常见近义形式。',src('biographic')),contexts:[c('biographic.s1','纪录片制作','The director used biographic details from the inventor’s notebooks but changed the dialogue to make the documentary easier to follow.','导演使用了发明家笔记中的传记资料，但改写了对白，使纪录片更容易理解。','The director used biographic details from the inventor’s notebooks / but changed the dialogue / to make the documentary easier to follow.','biographic 修饰 details；to make 表示修改对白的目的。','来自笔记的生平资料属于传记信息。')],mistakes:[m('The article is biographic because it explains the chemical structure of the sample, not anyone’s life.','The article is biochemical because it explains the chemical structure of the sample, not anyone’s life.','化学结构与传记无关；将 biographic 改成 biochemical。')],quiz:[q('biographic',1,1,'Biographic details are details about?','a person’s life','a cell’s chemical reaction','a two-part legislature','biographic 表示与某人生平有关。'),q('biographic',2,1,'A biographic film would most likely portray?','events from someone’s life','a purely imaginary planet with no characters','the price of a train ticket','传记电影以人生经历为材料。'),q('biographic',3,1,'Which adjective can often replace biographic?','biographical','bilingual','biological','biographical 常与 biographic 同义。'),q('biographic',4,1,'Choose the phrase that uses biographic correctly.','biographic information about the composer','biographic oxygen inside a flask','a biographic of two languages','形容词可修饰 composer 的生平信息。')]});
D('biographical',{etymology:e('biographical 由 biography 加形容词后缀 -ical 构成，表示与传记有关或以人生经历为基础；与 biographic 同义。',src('biographical')),contexts:[c('biographical.s1','文学评论','Although the novel is biographical, the author altered several dates and combined two real colleagues into one character.','这部小说虽以真实人生经历为基础，作者仍改动了几处日期，并把两位现实同事合成一个人物。','Although the novel is biographical / the author altered several dates / and combined two real colleagues into one character.','biographical 修饰 novel；although 表示“尽管基于生平，仍有改编”。','作品以人生经历为基础，体现传记体/传记相关义。')],mistakes:[m('The biographical account avoids all facts about the subject’s life and describes only an imaginary planet.','The science-fiction account avoids facts about a real person’s life and describes an imaginary planet.','不写真实人物生平的虚构星球故事并非传记性叙述。')],quiz:[q('biographical',1,1,'A biographical account tells?','events and facts from a person’s life','how to repair a bicycle','the chemical formula of a mineral','biographical 指与个人生平传记有关。'),q('biographical',2,1,'A novel based partly on its author’s life may be called?','biographical','biphenyl','belligerent','作品以真实生平为材料可称 biographical。'),q('biographical',3,1,'Which spelling is a common related adjective?','biographic','biographal','biographful','biographic 是 biographical 的相关形式。'),q('biographical',4,1,'Choose the natural phrase.','biographical notes on the composer','biographical two-language signs','biographically novel details','形容词 biographical 可修饰人物资料。')]});
D('biologically',{etymology:e('biologically 由 biological + 副词后缀 -ly 构成；biological 来自 biology（生物学），用于从生物体、基因或生命过程角度说明某事。',src('biologically')),contexts:[c('biologically.s1','物种关系','The two island populations look almost identical, but genetic testing showed that they are biologically distinct and reproduce at different times of year.','两个岛屿种群外观几乎相同，但基因检测显示它们在生物学上不同，繁殖季节也不同。','The two island populations look almost identical / but genetic testing showed / that they are biologically distinct / and reproduce at different times of year.','biologically 修饰形容词 distinct；that 引导 showed 的宾语从句。','基因与繁殖差异属于生物学层面的关系，符合词义。')],mistakes:[m('The twins are biologically unrelated because they share the same biological parents and DNA.','The twins are biologically related because they share the same biological parents and DNA.','共同亲生父母和 DNA 说明有生物学亲缘；unrelated 与事实矛盾。')],quiz:[q('biologically',1,1,'Biologically distinct species differ in?','features of living organisms such as genes or reproduction','the spelling of their names only','the color of a laboratory wall','biologically 指从生物体或生命过程角度。'),q('biologically',2,1,'“Biologically related” most directly refers to?','a genetic or family connection','a shared office schedule','two books printed together','biological kinship refers to genes or family relation。'),q('biologically',3,1,'Which base adjective forms biologically?','biological','biologist','biologyism','biologically 由 biological 加 -ly 构成。'),q('biologically',4,1,'The doctor says the two organs are biologically compatible. This concerns?','how they function within living bodies','whether their labels rhyme','how much they cost to ship','compatible 关系指生物体内能否相容。')]});
/* A9 checkpoint 4/4: entries 61–80. */
D('biologist',{etymology:e('biologist 由 biology 加人物后缀 -ist 构成；biology 来自希腊语 bios“生命”与 -logia“研究”。',src('biologist')),contexts:[c('biologist.s1','海洋生态','The marine biologist tagged each nesting turtle, recorded its shell length, and released it at the same stretch of beach before sunrise.','海洋生物学家给每只筑巢海龟做标记，记录甲壳长度，并在日出前把它放回同一段海滩。','The marine biologist tagged each nesting turtle / recorded its shell length / and released it at the same stretch of beach / before sunrise.','biologist 是研究生命的专业人员；三个并列动词描述现场研究步骤。','研究海龟和生命过程的人是生物学家。')],mistakes:[m('The biologist studied only the bridge’s load-bearing beams and never examined any organism.','The civil engineer studied only the bridge’s load-bearing beams and never examined any organism.','桥梁承重结构属于土木工程，不是生物学家研究的对象。')],quiz:[q('biologist',1,1,'A biologist studies?','living organisms and life processes','the history of a bridge','the grammar of legal contracts','biologist 指研究生物或生命过程的人。'),q('biologist',2,1,'A marine biologist might study?','nesting sea turtles','the price of a city bus','the stars’ chemical names only','海洋生物学家研究海洋生物。'),q('biologist',3,1,'The suffix -ist in biologist refers to?','a person who studies or practices a field','the past tense of a verb','a measure of time','-ist 构成人物名词。'),q('biologist',4,1,'Which professional would examine how a plant grows?','a biologist','a bidder','a belligerent','植物生长属于生物研究。')]});
D('biomass',{etymology:e('biomass 由 bio-“生物”与 mass“质量、总量”组合；可指某地或某类群活生物的总质量，也可指用于能源的有机物料。',src('biomass')),contexts:[c('biomass.s2','可再生能源','The village heats its school with biomass made from wood chips and crop waste, using residue that local farms would otherwise discard.','村里用木屑和作物废料制成的生物质为学校供暖，利用了当地农场原本会丢弃的残余物。','The village heats its school with biomass made from wood chips and crop waste / using residue / that local farms would otherwise discard.','biomass 在此为燃料的不可数名词；made from 说明原料来源。','有机废弃物被用于能源，符合生物质燃料义 s2。')],mistakes:[m('The biomass fuel was made only from aluminum cans and glass, with no organic material.','The recycled-material fuel was made from aluminum cans and glass, with no organic material.','生物质燃料来自有机物；纯金属和玻璃不是 biomass。')],quiz:[q('biomass',1,1,'In ecology, the biomass of a forest is?','the total mass of living organisms there','the number of roads through it','the weight of the clouds above it','生态学 biomass 指活生物的总质量。'),q('biomass',2,2,'Biomass fuel may be made from?','wood and crop waste','glass bottles only','pure iron filings','有机物如木材和作物废弃物可作生物质燃料。'),q('biomass',3,1,'Which example best fits biomass as fuel?','burning compressed plant residue for heat','melting a steel beam','using sand as a computer password','植物残余物是有机生物质燃料。'),q('biomass',4,1,'The word combines bio- with a term meaning?','mass or quantity','color','speech','biomass 的 mass 指质量/总量。')]});
D('biome',{etymology:e('现代生态学术语 biome 由 bio-“生命、生物”构成，指受气候与典型生物群落共同界定的大型生态区域；词形的更细来源不作臆断。',src('biome')),contexts:[c('biome.s1','生态地理','The tundra biome has a short growing season, frozen ground for much of the year, and plants adapted to cold winds and limited sunlight.','苔原生物群系生长期短，一年大部分时间地面冻结，植物适应寒风和有限日照。','The tundra biome has a short growing season / frozen ground for much of the year / and plants adapted to cold winds and limited sunlight.','biome 作可数名词，tundra 修饰说明是哪一种群系；adapted to 后接环境条件。','气候和典型生物共同构成苔原这一大型生态区。')],mistakes:[m('A biome is a single animal kept in an aquarium, with no relation to climate or other species.','An organism is a single animal kept in an aquarium, while a biome is a large ecological region shaped by climate and communities.','单只动物是 organism；biome 指由环境和生物群落界定的区域。')],quiz:[q('biome',1,1,'A biome is best described as?','a major ecological region such as desert or tundra','one individual animal','a device for measuring rainfall','biome 指大型生态群系。'),q('biome',2,1,'Which factors help distinguish a biome?','climate and characteristic communities','the color of a city’s buildings','the language on local road signs','气候与典型生物群落界定生态群系。'),q('biome',3,1,'The tundra is an example of a?','biome','bifocal lens','legal beneficiary','苔原是生物群系类型。'),q('biome',4,1,'A rainforest biome would include?','a climate region and its characteristic living communities','only one tree removed from its habitat','a map with no organisms shown','biome 包含区域及其典型生物群落。')]});
D('biometrics',{etymology:e('biometrics 由 bio-“生物”与 metrics“测量”构成；现代常指用指纹、面孔等身体特征识别身份，另有生物测量统计学义。',src('biometrics')),contexts:[c('biometrics.s1','机场安检','At the boarding gate, the traveler chose biometric verification and looked into the camera while the system matched her face to the passport photograph.','在登机口，旅客选择生物特征验证并看向摄像头，系统把她的面孔与护照照片进行匹配。','At the boarding gate / the traveler chose biometric verification / and looked into the camera / while the system matched her face to the passport photograph.','biometric 作形容词修饰 verification；while 从句说明核验同时进行的动作。','通过脸部身体特征确认身份，符合 biometrics 的识别技术义 s1。')],mistakes:[m('The airport’s biometrics system identified every passenger by asking them to choose a favorite color, without measuring any body feature.','The airport’s survey system identified passengers by asking them to choose a favorite color, without measuring any body feature.','不测量指纹、面孔等身体特征就不是生物识别；称作调查系统更准确。')],quiz:[q('biometrics',1,1,'An airport uses biometrics to identify a traveler by?','a fingerprint or face pattern','a handwritten favorite color','the traveler’s luggage weight only','身份识别义 biometrics 使用身体特征。'),q('biometrics',2,2,'Biometrics as a scientific field may also involve?','statistical analysis of biological measurements','the auction price of old books','the design of two-chamber parliaments','词条第二义是生物测量统计学。'),q('biometrics',3,1,'Which is a biometric identifier?','a person’s fingerprint','a boarding pass color','a suitcase brand','指纹是用于身份识别的生物特征。'),q('biometrics',4,1,'The elements bio- and metrics suggest?','measuring traits of living beings','writing about a city','speaking two languages','bio + metrics 与生物测量相关。')]});
D('biotic',{etymology:e('biotic 借自希腊语 biotikos“与生命有关的”，源于 bios“生命”；生态学中指由生物产生或涉及环境中生物的因素。',src('biotic')),contexts:[c('biotic.s1','湖泊生态','Predatory fish are a biotic factor in the lake because their feeding changes the number of smaller fish and affects competition for food.','掠食性鱼类是湖泊中的生物因素，因为它们捕食会改变小鱼数量，并影响食物竞争。','Predatory fish are a biotic factor in the lake / because their feeding changes the number of smaller fish / and affects competition for food.','biotic 修饰 factor；because 引出原因。','鱼类是活生物并影响生态环境，符合生物因素义。')],mistakes:[m('Water temperature is a biotic factor because it is a living animal in the lake.','Water temperature is an abiotic factor because it is a nonliving condition in the lake.','温度不是生物；它属于非生物环境因素 abiotic。')],quiz:[q('biotic',1,1,'A biotic factor in an ecosystem comes from?','living organisms','nonliving sunlight or temperature alone','a written rule','biotic 与生态中的生物有关。'),q('biotic',2,1,'Which is a biotic factor in a pond?','algae','water temperature','a rock','藻类是生物，属于 biotic factor。'),q('biotic',3,1,'The usual opposite of biotic is?','abiotic','bilingual','bipedal','abiotic 指非生物因素。'),q('biotic',4,1,'Predators are biotic because they?','are living organisms that interact with other life','are made of stone','measure the depth of water','掠食者是生物并与其他生物互动。')]});
D('biped',{etymology:e('biped 借自拉丁语 bipes/biped-，由 bi-“两个”与 pes、pedis“脚”构成，可作名词指两足动物，也可作形容词指两足的。',src('biped')),contexts:[c('biped.s1','动物学','A bird is a biped because it normally walks on two feet, even though it uses its wings rather than its legs to fly.','鸟属于两足动物，因为它通常用两只脚行走，即使它飞行时用的是翅膀。','A bird is a biped / because it normally walks on two feet / even though it uses its wings rather than its legs to fly.','biped 作可数名词；even though 引导让步从句。','鸟以两足行走，是两足动物的一个例子。')],mistakes:[m('A biped walks on four feet, and a horse is the clearest example.','A quadruped walks on four feet, and a horse is the clearest example.','四足动物是 quadruped；biped 指两足。')],quiz:[q('biped',1,1,'A biped is an animal that?','uses two feet for walking','has four wings for swimming','lives only under water','biped 名词指用两足行走的动物。'),q('biped',2,2,'“The dinosaur was biped” means it?','had or walked on two feet','had no legs','could only move by rolling','biped 也可作形容词指两足的。'),q('biped',3,1,'A human and an ostrich are examples of?','bipeds','fish','quadrupeds','人和鸵鸟都以两足行走。'),q('biped',4,1,'The prefix bi- in biped indicates?','two','one','many','bi- 表示两个脚。')]});
D('bipedal',{etymology:e('bipedal 由 bi-“两个”、ped-“脚”与形容词后缀 -al 构成，表示用两条腿行走或移动。',src('bipedal')),contexts:[c('bipedal.s1','人类进化','The fossil trackway showed a bipedal animal walking across soft ash, with alternating left and right footprints preserved in the rock.','这组化石足迹显示一种两足动物走过柔软火山灰，左右交替的脚印保存在岩石中。','The fossil trackway showed a bipedal animal / walking across soft ash / with alternating left and right footprints preserved in the rock.','bipedal 修饰 animal；walking 短语补充描述行走方式。','交替左右足迹显示依两条腿行走，符合 bipedal 义。')],mistakes:[m('The lizard moved bipedally on all four legs at the same time.','The lizard moved quadrupedally on all four legs at the same time.','四肢同时行走是四足方式，不是 bipedal。')],quiz:[q('bipedal',1,1,'Bipedal movement uses?','two legs','four legs','no limbs at all','bipedal 指用两条腿移动。'),q('bipedal',2,1,'Which animal is commonly described as bipedal?','an ostrich','a dog walking on four legs','a snake slithering','鸵鸟以两足行走。'),q('bipedal',3,1,'Choose the correct phrase.','bipedal walking','bipedally feet','bipedalism animal walkly','bipedal 可修饰 walking。'),q('bipedal',4,1,'In bipedal, the element ped refers to?','feet or legs','feathers','water','ped 与脚有关。')]});
D('biphenyl',{etymology:e('biphenyl 是有机化学名称，由 bi-“两个”与 phenyl（苯基）组合，指两个苯环通过碳—碳键直接相连的化合物。',src('biphenyl')),contexts:[c('biphenyl.s1','有机化学','The chemist modeled biphenyl as two benzene rings joined by a single bond and checked whether the rings twisted out of the same plane.','化学家把联苯建模为两个苯环由一根单键相连，并检查两环是否扭转到不同平面。','The chemist modeled biphenyl as two benzene rings joined by a single bond / and checked whether the rings twisted out of the same plane.','biphenyl 作化合物名；joined 过去分词短语说明苯环之间的连接方式。','分子结构为两个相连苯环，符合联苯义。')],mistakes:[m('Biphenyl consists of one benzene ring with no second ring or connecting bond.','Biphenyl consists of two benzene rings joined by a bond.','只有一个苯环不能称 biphenyl；bi- 指两个苯基环。')],quiz:[q('biphenyl',1,1,'Biphenyl contains?','two benzene rings joined together','one isolated methane molecule','three sugar rings','联苯由两个苯环相连组成。'),q('biphenyl',2,1,'A chemist discussing biphenyl is working with?','an organic compound','a bird species','a two-house parliament','biphenyl 是有机化合物。'),q('biphenyl',3,1,'The prefix bi- in biphenyl signals?','two phenyl groups','one water molecule','a biological measurement','bi- 表示两个苯基。'),q('biphenyl',4,1,'Which diagram would represent biphenyl?','two linked hexagonal benzene rings','one straight chain with no rings','two unconnected pieces of paper','联苯是两个苯环直接相连。')]});
D('birch',{etymology:e('birch 源自古英语 beorc/birce，与其他日耳曼语族中表示桦树的词同源；指常有白色或银色、树皮薄而易剥的树。',src('birch')),contexts:[c('birch.s1','林地','A silver birch leaned over the stream, its pale bark peeling in thin strips while new leaves opened along the branches.','一棵银桦树斜伸到溪流上方，浅色树皮一层层薄薄剥落，枝条上新叶正在舒展。','A silver birch leaned over the stream / its pale bark peeling in thin strips / while new leaves opened along the branches.','birch 作可数名词；while 引导两个同时发生的景象。','浅色易剥的树皮是桦树的典型识别特征。')],mistakes:[m('The birch had dark rough bark that could never peel, and it was identified by its tropical palm leaves.','The palm had dark rough bark that could never peel, and it was identified by its tropical leaves.','棕榈叶与桦树特征不符；该树应另称 palm。')],quiz:[q('birch',1,1,'A birch is a tree often recognized by?','thin pale bark that can peel','a trunk covered in large scales','fruit that grows underwater','桦树常有浅色、易剥的薄树皮。'),q('birch',2,1,'Which tree is a birch?','a silver-barked tree by a stream','a cactus with spines','a palm with a tall tropical crown','银桦是桦树的一种。'),q('birch',3,1,'Birch wood comes from?','the birch tree','the bark of a fish','a mineral seam','birch 指桦树及其木材。'),q('birch',4,1,'Choose a natural phrase.','a birch forest','a birch flock','a birch of water','多棵桦树构成 birch forest。')]});
D('birdlike',{etymology:e('birdlike 是英语复合词 bird + -like，表示外形、动作或体态具有鸟的轻盈或相似特征。',src('birdlike')),contexts:[c('birdlike.s1','人物动作','The dancer made quick, birdlike movements across the stage, turning lightly on her toes before leaping into the final pose.','舞者在舞台上做出敏捷轻盈、像鸟一样的动作，先用脚尖轻旋，再跃入最后的姿势。','The dancer made quick, birdlike movements across the stage / turning lightly on her toes / before leaping into the final pose.','birdlike 作形容词修饰 movements；before leaping 表示跃起前的动作。','敏捷轻盈的动作如鸟般灵巧，符合相似特征义。')],mistakes:[m('The birdlike machine was a heavy tank that moved slowly on tracks and could not fly.','The tanklike machine was heavy, moved slowly on tracks, and could not fly.','沉重缓慢的坦克与鸟的轻盈或外形无关；tanklike 更贴切。')],quiz:[q('birdlike',1,1,'A birdlike movement may be?','quick and light like a bird','heavy and slow like a stone','exactly the same as swimming','birdlike 可形容轻盈敏捷的动作。'),q('birdlike',2,1,'Which description is birdlike?','a delicate, rapid turn of the head','a slow roll of a large truck','a square wall with no movement','鸟样特征可用于灵巧或轻盈动作。'),q('birdlike',3,1,'The suffix -like means?','similar to or characteristic of','without any','the past form of','-like 表示像……或具有……特征。'),q('birdlike',4,1,'A birdlike silhouette would resemble?','the shape of a bird','a stone staircase','a glass bottle only','birdlike 也可以描述外形像鸟。')]});
D('Birmingham',{etymology:e('Birmingham 源自古英语 Beormingahām，通常解释为“Beorma 一族/后裔的家园”；该专名可指英格兰中部城市，也可指美国亚拉巴马州城市。',src('Birmingham')),contexts:[c('Birmingham.s1','英国城市','The train from London reached Birmingham before noon, giving the visitors an afternoon to explore the city’s canals and industrial museums.','从伦敦出发的列车中午前抵达伯明翰，游客因此有一个下午参观这座城市的运河和工业博物馆。','The train from London reached Birmingham before noon / giving the visitors an afternoon / to explore the city’s canals and industrial museums.','Birmingham 作专有地名首字母大写；reach 后直接接地点，不加 to。','伦敦出发、运河和工业博物馆将语境锁定英格兰中部城市。')],mistakes:[m('The train arrived to Birmingham at noon, where the city is the capital of Germany.','The train arrived in Birmingham at noon, a major city in the English Midlands.','大城市前 arrive 通常用 in；Birmingham 不在德国。')],quiz:[q('Birmingham',1,1,'Birmingham in the English Midlands is?','a major city in central England','the capital of Germany','a small island in the Pacific','词条指英格兰中部的大城市。'),q('Birmingham',2,1,'Which other place also bears the name Birmingham?','a city in Alabama, USA','a city in Iceland','a town on the Moon','Birmingham 也指美国亚拉巴马州城市。'),q('Birmingham',3,1,'Choose the correct sentence.','We arrived in Birmingham before lunch.','We arrived to Birmingham before lunch.','We arrived at Birmingham before lunch.','到大城市通常用 arrive in。'),q('Birmingham',4,1,'The old industrial canals most likely point to?','Birmingham in England’s Midlands','Birmingham as a German capital','a city named Berlin','运河和工业史对应英格兰伯明翰。')]});
D('birthright',{etymology:e('birthright 由 birth + right 构成，指因出生或家族身份而自然享有的权利或特权；不是出生后必须通过考试取得的资格。',src('birthright')),contexts:[c('birthright.s1','公民权利','The residents argued that access to clean water should be treated as a birthright, not a luxury reserved for families who could pay extra fees.','居民认为，获得清洁用水应被视为与生俱来的权利，而非只留给能额外付费家庭的奢侈品。','The residents argued that access to clean water should be treated as a birthright / not a luxury reserved for families / who could pay extra fees.','treat A as a birthright 表示把 A 视为生来应有的权利；not 作对照。','居民把基本权益视为人人应有的权利，符合词条义。')],mistakes:[m('She called the prize a birthright because she had to pass a difficult exam and earn it through years of work.','She called the prize an earned award because she had to pass a difficult exam and earn it through years of work.','经考试和努力挣得的奖项不是因出生自然享有的 birthright。')],quiz:[q('birthright',1,1,'A birthright is something a person?','is entitled to by birth or family status','must buy at an auction','earns only by winning a race','birthright 指因出生而有的权利或特权。'),q('birthright',2,1,'If clean water is called a birthright, the speaker means?','everyone should have it as a basic entitlement','only wealthy people may use it','it is a prize for passing an exam','表达将清洁水视为人人的基本权利。'),q('birthright',3,1,'Which is least likely to be a birthright?','a medal earned by winning a contest','a right attached to birth','an inheritance tied to eldest-child status','竞赛获胜后挣得的奖牌不是生来权利。'),q('birthright',4,1,'The word combines birth with?','right, an entitlement','bird, an animal','bright, a color','birthright 是 birth + right 的透明复合词。')]});
D('bisect',{etymology:e('bisect 借自拉丁语 bisecare，由 bi-“两次/二”与 secare“切”构成；数学中常指把线段、角或区域分为两部分，往往为相等两半。',src('bisect')),contexts:[c('bisect.s1','城市规划','A new cycle path will bisect the park from north to south, dividing the open lawn into two sections while keeping both playgrounds accessible.','一条新自行车道将从北到南穿过公园，把草坪分成两部分，同时让两个游乐场都能通行。','A new cycle path will bisect the park from north to south / dividing the open lawn into two sections / while keeping both playgrounds accessible.','bisect 作及物动词，直接接被分开的区域；dividing 补充结果。','道路把区域分为两部分，体现 bisect 的对分义。')],mistakes:[m('The line bisects the square into three equal regions.','The line trisects the square into three equal regions.','分成三部分是 trisect；bisect 是分成两部分。')],quiz:[q('bisect',1,1,'To bisect a line is to divide it into?','two parts','three parts','four unequal circles','bi- 表示二，bisect 是分成两部分。'),q('bisect',2,1,'A road that bisects a park?','cuts across it and divides it into two areas','runs around its outside without entering','turns it into a lake','道路穿过并把公园分为两区。'),q('bisect',3,1,'Which tool helps bisect an angle accurately?','a compass and straightedge','a kitchen scale','a thermometer','几何作图工具可用于平分角。'),q('bisect',4,1,'Complete: “The river ___ the valley into eastern and western halves.”','bisects','beseeches','bifocals','bisects 直接接被分割的对象。')]});
D('biter',{etymology:e('biter 是 bite 加施事者后缀 -er 构成，指会用牙齿咬人或咬住东西的人或动物。',src('biter')),contexts:[c('biter.s1','动物收容','The shelter marked the dog as a known biter, so staff introduced visitors slowly and used a secure gate during each meeting.','收容所把这只狗标记为已知会咬人的动物，因此工作人员让访客慢慢接近，并在每次会面时使用安全门。','The shelter marked the dog as a known biter / so staff introduced visitors slowly / and used a secure gate during each meeting.','biter 是施事名词；known biter 指有咬人记录的动物。','狗曾用牙齿伤人，符合“会咬人的动物”义。')],mistakes:[m('The dog was called a biter because it never used its teeth and had never snapped at anyone.','The dog was called gentle because it never used its teeth and had never snapped at anyone.','从未咬人不能称为 biter；gentle 与该行为描述相符。')],quiz:[q('biter',1,1,'A dog described as a biter is one that?','has a tendency to bite','has never shown its teeth','only eats plants','biter 指会咬人的动物。'),q('biter',2,1,'Which person might be called a biter?','a child who repeatedly bites other children','a child who quietly reads','a child who paints a picture','biter 也可指习惯咬人的人。'),q('biter',3,1,'The suffix -er in biter marks?','the one that performs the action','a place where biting is forbidden','the adjective for bitter taste','-er 构成做 bite 动作的人或物。'),q('biter',4,1,'Choose the natural phrase.','a known biter','a biter of very polite greetings','biterly at the door','known biter 指有咬人记录者。')]});
D('bitterly',{etymology:e('bitterly 由 bitter 加副词后缀 -ly 构成；除表示味道强烈苦涩外，也修饰抱怨、反对或哭泣等强烈痛苦、怨恨的方式。',src('bitterly')),contexts:[c('bitterly.s1','劳资谈判','Workers complained bitterly after management cancelled the promised bonus without explanation, and the union demanded a new meeting.','管理层毫无解释地取消承诺奖金后，工人们激烈抱怨，工会要求重新开会。','Workers complained bitterly / after management cancelled the promised bonus without explanation / and the union demanded a new meeting.','bitterly 修饰 complained；after 引导取消奖金后的时间从句。','工人带着强烈不满抱怨，符合 s1。')],mistakes:[m('She bitterly praised the unfair cuts and said she was delighted to lose her promised pay.','She bitterly opposed the unfair cuts and said she was angry to lose her promised pay.','对不公平削减表示高兴与“bitterly”怨愤含义相反；改成 opposed/angry。')],quiz:[q('bitterly',1,1,'To complain bitterly is to complain?','with intense anger or disappointment','in a cheerful and grateful way','without making any sound or response','bitterly 可表示带着强烈怨愤地。'),q('bitterly',2,1,'“She was bitterly disappointed” means she was?','deeply disappointed','slightly curious','pleased beyond expectation','bitterly 加强失望的程度。'),q('bitterly',3,1,'Choose the natural phrase.','bitterly opposed to the change','bitterly sweetly agreed without concern','bitterly of the meeting','bitterly 可修饰反对，表示强烈反对。'),q('bitterly',4,1,'Which taste could be described as bitterly unpleasant?','an intensely sharp, bitter flavor','plain cold water with no taste','sweet honey','bitterly 也可强化味道的苦涩感。')]});
D('bitterness',{etymology:e('bitterness 由 bitter 加名词后缀 -ness 构成，可指苦味，也可比喻因不公、失望而长期存在的怨恨与心酸。',src('bitterness')),contexts:[c('bitterness.s2','长期失望','Years of bitterness followed the broken promise, and the former partners avoided one another even after the business dispute was settled.','承诺被违背后，多年怨恨挥之不去；即使商业纠纷解决，前合伙人仍互相回避。','Years of bitterness followed the broken promise / and the former partners avoided one another / even after the business dispute was settled.','bitterness 作不可数名词；followed 表示发生在失信之后。','纠纷解决后仍有长期怨恨，符合 s2 情绪义。')],mistakes:[m('The bitterness of the lemon vanished because it had an intensely sweet, sugary flavor.','The bitterness of the lemon vanished because it had no sharp or unpleasant taste.','强烈甜味与苦味相反；需要说明不再有苦涩味。')],quiz:[q('bitterness',1,1,'Bitterness in coffee describes?','a sharp, unpleasant taste','a sweet smell','a lack of any flavor','bitterness 可指苦味。'),q('bitterness',2,2,'Bitterness after an unfair dismissal is?','lasting anger and hurt','a chemical taste in tea only','a sudden happy surprise','比喻义是因不公而久存的愤懑。'),q('bitterness',3,1,'The suffix -ness turns bitter into a?','noun naming a quality or state','past-tense verb','plural of a person','-ness 构成表示性质或状态的名词。'),q('bitterness',4,2,'Which sentence uses the emotional sense?','Bitterness remained long after the apology.','The soup’s bitterness came from the coffee beans.','The bitterness measured five centimeters.','多年后仍怨恨，使用情绪义。')]});
D('bitumen',{etymology:e('bitumen 经拉丁语 bitumen 进入英语，指天然或石油来源的黑色黏稠烃类物质，常用于铺路和防水。',src('bitumen')),contexts:[c('bitumen.s1','道路施工','Road crews heated bitumen until it flowed easily, then spread it across the prepared surface to seal gaps before laying the final layer.','道路施工人员把沥青加热到易于流动，再铺在已准备好的路面上封住缝隙，然后铺设最终层。','Road crews heated bitumen until it flowed easily / then spread it across the prepared surface / to seal gaps / before laying the final layer.','heat bitumen 描述材料处理；to seal 表目的。','加热后铺设、封路面的黑色材料是沥青。')],mistakes:[m('The crew poured bitumen to make the road waterproof, but the material was a clear, dry gas.','The crew poured bitumen to make the road waterproof, using a thick black material.','沥青是黑色黏稠物质，不是干燥透明气体。')],quiz:[q('bitumen',1,1,'Bitumen is commonly used for?','road paving and waterproofing','making transparent window glass','feeding garden birds','沥青常用于铺路和防水。'),q('bitumen',2,1,'Which description fits bitumen?','a thick, dark, sticky hydrocarbon mixture','a clear gas with no mass','a sweet liquid made from fruit','bitumen 是黑色黏稠烃类混合物。'),q('bitumen',3,1,'Road workers may heat bitumen so it?','spreads across the surface','turns into a tree','becomes a paper label','加热能让黏稠沥青易于铺展。'),q('bitumen',4,1,'Bitumen is most closely associated with?','asphalt and road surfaces','bilingual dictionaries','bird feathers','道路沥青与 bitumen 密切相关。')]});
D('bituminous',{etymology:e('bituminous 由 bitumen 加形容词后缀 -ous 构成，意为含沥青的或具有沥青质特征的；bituminous coal 是常见搭配。',src('bituminous')),contexts:[c('bituminous.s1','矿物资源','The mine produced bituminous coal, a dark, carbon-rich fuel that left soot on equipment unless workers cleaned the conveyors regularly.','矿井产出烟煤，这种富含碳的深色燃料若不定期清洁输送带，会在设备上留下煤烟。','The mine produced bituminous coal / a dark, carbon-rich fuel / that left soot on equipment / unless workers cleaned the conveyors regularly.','bituminous 修饰 coal；unless 引导条件从句。','烟煤属于含沥青质的煤种，符合 s1。')],mistakes:[m('The sample was bituminous because it contained no bitumen-like material and dissolved as clean water.','The sample was non-bituminous because it contained no bitumen-like material and dissolved as clean water.','不含沥青质就不能称 bituminous；改为 non-bituminous。')],quiz:[q('bituminous',1,1,'Bituminous material is?','containing or resembling bitumen','made entirely of fresh water','unrelated to hydrocarbons','bituminous 表示含沥青或像沥青。'),q('bituminous',2,1,'Bituminous coal is a kind of?','coal containing bituminous matter','transparent ice','a type of garden flower','bituminous coal 指烟煤。'),q('bituminous',3,1,'The suffix -ous often forms an adjective meaning?','having or containing something','the person who performs an action','the past of a verb','-ous 常表示具有某种性质或成分。'),q('bituminous',4,1,'Choose the standard phrase.','bituminous coal','bituminously coal','coal bitumenal','常见搭配是 bituminous coal。')]});
D('blackbird',{etymology:e('blackbird 是 black + bird 的英语复合词，指羽毛大多为黑色的鸣禽；不同地区用该名的具体鸟种可能不同。',src('blackbird')),contexts:[c('blackbird.s1','花园观察','A blackbird sang from the garden wall at dawn, then hopped down to search the damp lawn for worms after the rain.','黎明时一只乌鸫在花园墙上鸣唱，雨后又跳到潮湿草坪上寻找蚯蚓。','A blackbird sang from the garden wall at dawn / then hopped down / to search the damp lawn for worms / after the rain.','blackbird 作可数名词；to search 表示跳下来的目的。','黑色羽毛的鸣禽在墙上唱歌觅食，符合鸟类义。')],mistakes:[m('The blackbird was a bright blue fish swimming beneath the garden wall.','The blackbird was a dark-feathered songbird perched above the garden wall.','鱼不是鸟；blackbird 指黑色鸣禽而非水生动物。')],quiz:[q('blackbird',1,1,'A blackbird is generally?','a songbird with mostly black feathers','a small green frog','a fish with a dark tail','blackbird 指羽色以黑为主的鸣禽。'),q('blackbird',2,1,'What might a blackbird do in a garden?','sing from a wall and search for worms','build a nest underwater','grow leaves from its feathers','鸣唱和觅食是鸟的典型行为。'),q('blackbird',3,1,'The compound blackbird combines?','a color and a bird','a tool and a room','a language and a number','词由 black 与 bird 构成。'),q('blackbird',4,1,'Which phrase uses blackbird correctly?','a blackbird singing in a tree','a blackbird of boiling water','a flock of blackbirdly leaves','树上的鸣禽可称 blackbird。')]});
D('blackcap',{etymology:e('blackcap 是 black + cap 的复合词，以雄鸟头顶像黑帽的一簇羽毛命名；指一种小型鸣禽，雌鸟头顶颜色可较浅。',src('blackcap')),contexts:[c('blackcap.s1','鸟类观察','The birdwatcher identified a male blackcap by its neat black crown and noted its soft song before it disappeared into the ivy.','观鸟者凭雄鸟整齐的黑色头顶认出这只黑顶林莺，并在它消失进常春藤前记下柔和的歌声。','The birdwatcher identified a male blackcap by its neat black crown / and noted its soft song / before it disappeared into the ivy.','blackcap 作可数名词；by 引出辨认依据。','雄鸟头顶的黑羽像帽子，是名称和辨认特征。')],mistakes:[m('The male blackcap was identified by its bright red cap.','The male blackcap was identified by its black cap.','雄性 blackcap 的辨认特征是黑色头顶；把 red 改为 black 即可。')],quiz:[q('blackcap',1,1,'A male blackcap is recognized by?','a neat black cap of feathers','a long blue bill','a white shell','雄鸟头顶有整齐黑羽。'),q('blackcap',2,1,'A blackcap is a type of?','small songbird','large ocean mammal','flowering shrub','blackcap 指小型鸣禽。'),q('blackcap',3,1,'The name blackcap combines black with?','cap, referring to its crown feathers','cape, meaning a coastline','capable, meaning skillful','名称中的 cap 指像帽子的头顶羽毛。'),q('blackcap',4,1,'Where might a blackcap be heard?','singing in garden ivy','roaring beneath the sea','buzzing inside a computer','黑顶林莺会在灌木或藤蔓间鸣唱。')]});


})();
